screenPanels.initJs:
function(container, apiUrl, tables) {
  // ログイン試行回数を追跡
  let loginAttempts = parseInt(localStorage.getItem('loginAttempts') || '0');
  let lastFailedLogin = localStorage.getItem('lastFailedLogin');

  // アカウントロック状態をチェック
  function isAccountLocked() {
    if (loginAttempts >= 5 && lastFailedLogin) {
      const lockTime = new Date(lastFailedLogin).getTime();
      const now = new Date().getTime();
      // 30分間ロック
      return (now - lockTime) < (30 * 60 * 1000);
    }
    return false;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  // エラーメッセージ非表示
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.display = 'none';
  }

  // バリデーション
  function validateForm(userId, password) {
    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|<\/script|DROP TABLE|SELECT \*|INSERT INTO|DELETE FROM|UPDATE SET/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // アカウントロックチェック
      if (isAccountLocked()) {
        showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        return;
      }

      // ユーザー一覧を取得して認証
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました');
        return;
      }

      // 認証チェック（実際の実装では暗号化されたパスワードと比較）
      const user = users.find(u => u.ユーザー名 === userId && u.有効フラグ === true);

      if (!user) {
        // ログイン失敗回数を増加
        loginAttempts++;
        localStorage.setItem('loginAttempts', loginAttempts.toString());
        localStorage.setItem('lastFailedLogin', new Date().toISOString());

        showError('ユーザーIDまたはパスワードが正しくありません');
        return;
      }

      // パスワード検証（簡易実装 - 実際はハッシュ比較）
      // ここでは demo 用に 'password123' を正しいパスワードとする
      if (password !== 'password123') {
        loginAttempts++;
        localStorage.setItem('loginAttempts', loginAttempts.toString());
        localStorage.setItem('lastFailedLogin', new Date().toISOString());

        showError('ユーザーIDまたはパスワードが正しくありません');
        return;
      }

      // ログイン成功 - 試行回数リセット
      localStorage.removeItem('loginAttempts');
      localStorage.removeItem('lastFailedLogin');

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // セッション保存
      sessionStorage.setItem('currentUser', JSON.stringify(user));
      if (rememberMe) {
        localStorage.setItem('rememberedUser', JSON.stringify(user));
      }

      // メイン画面に遷移
      window.showScreen("scr-1778907133295");

    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました');
    }
  }

  // パスワード表示切り替え
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const passwordInput = container.querySelector('#password');

  togglePasswordBtn.addEventListener('click', () => {
    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      togglePasswordBtn.textContent = '🙈';
    } else {
      passwordInput.type = 'password';
      togglePasswordBtn.textContent = '👁';
    }
  });

  // フォーム送信処理
  const loginForm = container.querySelector('#login-form');
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;
    const rememberMe = container.querySelector('#remember-me').checked;

    if (!validateForm(userId, password)) {
      return;
    }

    await handleLogin(userId, password, rememberMe);
  });

  // パスワード忘れリンク
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実装時は適切な画面IDに変更）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // 自動ログインチェック（記憶されたユーザー情報があれば）
  const rememberedUser = localStorage.getItem('rememberedUser');
  if (rememberedUser) {
    try {
      const user = JSON.parse(rememberedUser);
      sessionStorage.setItem('currentUser', JSON.stringify(user));
      window.showScreen("scr-1778907133295");
    } catch (error) {
      localStorage.removeItem('rememberedUser');
    }
  }

  // ホバー効果
  const loginButton = container.querySelector('#login-button');
  loginButton.addEventListener('mouseenter', () => {
    loginButton.style.background = 'var(--primary-hover)';
  });
  loginButton.addEventListener('mouseleave', () => {
    loginButton.style.background = 'var(--primary)';
  });

  // フォーカス効果
  const inputs = container.querySelectorAll('input[type="text"], input[type="password"]');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let elapsedTimer = null;
  let isPaused = false;
  let pauseStartTime = null;
  let totalPauseTime = 0;
  let hasUnsavedChanges = false;

  // DOM要素の取得
  const workItemSelect = container.querySelector('#work-item-select');
  const startBtn = container.querySelector('#start-btn');
  const endBtn = container.querySelector('#end-btn');
  const pauseBtn = container.querySelector('#pause-btn');
  const saveBtn = container.querySelector('#save-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const elapsedTimeDisplay = container.querySelector('#elapsed-time');
  const currentDatetime = container.querySelector('#current-datetime');
  const workMemo = container.querySelector('#work-memo');
  const pauseReason = container.querySelector('#pause-reason');
  const pauseReasonSection = container.querySelector('#pause-reason-section');
  const confirmPauseBtn = container.querySelector('#confirm-pause-btn');
  const cancelPauseBtn = container.querySelector('#cancel-pause-button');
  const historyTbody = container.querySelector('#history-tbody');
  const errorMessage = container.querySelector('#error-message');
  const workMemoCount = container.querySelector('#work-memo-count');
  const pauseReasonCount = container.querySelector('#pause-reason-count');

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    window.aivicApi.list(3).then(items => {
      if (items) {
        workItemSelect.innerHTML = '<option value="">選択してください</option>';
        items.filter(item => item.有効フラグ).forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });
        updateStartButtonState();
      }
    });
  }

  // 本日の作業履歴を描画
  function renderTodayHistory(records) {
    const today = new Date().toISOString().split('T')[0];
    const todayRecords = records.filter(r => r.作業日 && r.作業日.startsWith(today));

    historyTbody.innerHTML = todayRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${String(record.作業時間 % 60).padStart(2, '0')}` : '-';

      return `
        <tr data-id="${record.作業記録ID}">
          <td style="padding: 6px 10px; font-size: 13px;">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.作業種別 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${workTime}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.進捗状況 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 現在日時の更新
  function updateCurrentTime() {
    const now = new Date();
    currentDatetime.textContent = now.toLocaleString('ja-JP');
  }

  // 経過時間の更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime;

    if (isPaused && pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }
    elapsed -= totalPauseTime;

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    elapsedTimeDisplay.textContent = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  // 開始ボタンの状態更新
  function updateStartButtonState() {
    startBtn.disabled = !workItemSelect.value || currentWorkRecord !== null;
  }

  // エラーメッセージの表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 文字数カウント更新
  function updateCharCount(textarea, countElement) {
    countElement.textContent = textarea.value.length;
  }

  // 未保存変更の検知
  function markUnsaved() {
    hasUnsavedChanges = true;
  }

  // 作業開始
  startBtn.addEventListener('click', () => {
    if (!workItemSelect.value) {
      showError('作業項目を選択してください');
      return;
    }

    startTime = new Date();
    totalPauseTime = 0;
    isPaused = false;
    pauseStartTime = null;

    currentWorkRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証済みユーザーIDを使用
      作業日: startTime.toISOString(),
      作業開始時刻: startTime.toISOString(),
      作業種別: workItemSelect.options[workItemSelect.selectedIndex].text,
      進捗状況: '作業中',
      承認状態: '未承認'
    };

    startBtn.disabled = true;
    endBtn.disabled = false;
    pauseBtn.disabled = false;
    workItemSelect.disabled = true;

    elapsedTimer = setInterval(updateElapsedTime, 1000);
    updateElapsedTime();
    markUnsaved();
  });

  // 作業終了
  endBtn.addEventListener('click', () => {
    if (!currentWorkRecord) {
      showError('作業が開始されていません');
      return;
    }

    if (isPaused) {
      showError('作業が中断中です。先に再開してください');
      return;
    }

    const endTime = new Date();
    const workTimeMinutes = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60));

    currentWorkRecord.作業終了時刻 = endTime.toISOString();
    currentWorkRecord.作業時間 = workTimeMinutes;
    currentWorkRecord.進捗状況 = '完了';
    currentWorkRecord.作業内容 = workMemo.value;

    clearInterval(elapsedTimer);

    startBtn.disabled = false;
    endBtn.disabled = true;
    pauseBtn.disabled = true;
    saveBtn.disabled = false;
    workItemSelect.disabled = false;

    updateStartButtonState();
  });

  // 中断
  pauseBtn.addEventListener('click', () => {
    if (!currentWorkRecord) {
      showError('作業が開始されていません');
      return;
    }

    if (isPaused) {
      // 再開
      const now = new Date();
      totalPauseTime += (now - pauseStartTime);
      isPaused = false;
      pauseStartTime = null;
      pauseBtn.textContent = '中断';
      currentWorkRecord.進捗状況 = '作業中';
    } else {
      // 中断理由入力画面を表示
      pauseReasonSection.style.display = 'block';
      pauseReason.value = '';
      updateCharCount(pauseReason, pauseReasonCount);
    }
  });

  // 中断確定
  confirmPauseBtn.addEventListener('click', () => {
    if (!pauseReason.value.trim()) {
      showError('中断理由を入力してください');
      return;
    }

    pauseStartTime = new Date();
    isPaused = true;
    pauseBtn.textContent = '再開';
    currentWorkRecord.進捗状況 = '中断';

    // 中断記録を保存
    const pauseRecord = {
      作業記録ID: currentWorkRecord.作業記録ID || 'temp-id',
      中断開始日時: pauseStartTime.toISOString(),
      中断理由区分: '作業中断',
      中断理由詳細: pauseReason.value,
      対応状況: '対応中',
      記録者ID: 'current-user-id'
    };

    window.aivicApi.save(2, pauseRecord);

    pauseReasonSection.style.display = 'none';
    markUnsaved();
  });

  // 中断キャンセル
  cancelPauseBtn.addEventListener('click', () => {
    pauseReasonSection.style.display = 'none';
  });

  // 保存
  saveBtn.addEventListener('click', async () => {
    if (!currentWorkRecord) {
      showError('保存する作業記録がありません');
      return;
    }

    const saved = await window.aivicApi.save(1, currentWorkRecord);
    if (saved) {
      currentWorkRecord = null;
      startTime = null;
      hasUnsavedChanges = false;

      // UI リセット
      workItemSelect.value = '';
      workMemo.value = '';
      elapsedTimeDisplay.textContent = '00:00:00';

      startBtn.disabled = false;
      endBtn.disabled = true;
      pauseBtn.disabled = true;
      saveBtn.disabled = true;
      workItemSelect.disabled = false;
      pauseBtn.textContent = '中断';

      updateStartButtonState();

      // 履歴を再読み込み
      const records = await window.aivicApi.list(1);
      if (records) renderTodayHistory(records);
    }
  });

  // キャンセル
  cancelBtn.addEventListener('click', () => {
    if (hasUnsavedChanges && !confirm('未保存の変更があります。破棄してもよろしいですか？')) {
      return;
    }

    // 作業中の場合は停止
    if (elapsedTimer) {
      clearInterval(elapsedTimer);
    }

    // 状態をリセット
    currentWorkRecord = null;
    startTime = null;
    isPaused = false;
    pauseStartTime = null;
    totalPauseTime = 0;
    hasUnsavedChanges = false;

    // UI リセット
    workItemSelect.value = '';
    workMemo.value = '';
    pauseReason.value = '';
    elapsedTimeDisplay.textContent = '00:00:00';
    pauseReasonSection.style.display = 'none';

    startBtn.disabled = false;
    endBtn.disabled = true;
    pauseBtn.disabled = true;
    saveBtn.disabled = true;
    workItemSelect.disabled = false;
    pauseBtn.textContent = '中断';

    updateStartButtonState();
    updateCharCount(workMemo, workMemoCount);
    updateCharCount(pauseReason, pauseReasonCount);
  });

  // 作業項目選択時
  workItemSelect.addEventListener('change', () => {
    updateStartButtonState();
    markUnsaved();
  });

  // 文字数カウント
  workMemo.addEventListener('input', () => {
    updateCharCount(workMemo, workMemoCount);
    markUnsaved();
  });

  pauseReason.addEventListener('input', () => {
    updateCharCount(pauseReason, pauseReasonCount);
  });

  // 削除ボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      await window.aivicApi.delete(1, deleteBtn.dataset.id);
      const records = await window.aivicApi.list(1);
      if (records) renderTodayHistory(records);
    }
  });

  // 初期化
  loadWorkItems();
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);

  // 初期データの読み込みと描画
  window.aivicApi.list(1).then(records => {
    if (records) renderTodayHistory(records);
  });

  updateCharCount(workMemo, workMemoCount);
  updateCharCount(pauseReason, pauseReasonCount);
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  const errorMessage = container.querySelector("#error-message");
  const noResults = container.querySelector("#no-results");
  const tableWrap = container.querySelector(".table-wrap");

  let allWorkRecords = [];
  let allWorkItems = [];
  let allInterruptions = [];

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = "block";
    setTimeout(() => {
      errorMessage.style.display = "none";
    }, 5000);
  }

  // 日付フォーマット関数
  function formatDate(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleDateString("ja-JP");
  }

  // 時刻フォーマット関数
  function formatTime(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleTimeString("ja-JP", { hour: "2-digit", minute: "2-digit" });
  }

  // 作業時間フォーマット関数（分を時間:分に変換）
  function formatWorkTime(minutes) {
    if (!minutes) return "";
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, "0")}`;
  }

  // 中断回数を計算する関数
  function getInterruptionCount(workRecordId) {
    return allInterruptions.filter(i => i.作業記録ID === workRecordId).length;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (rows.length === 0) {
      tableWrap.style.display = "none";
      noResults.style.display = "block";
      return;
    }

    tableWrap.style.display = "block";
    noResults.style.display = "none";

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.作業記録ID || r.id}" style="height: 36px;">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(r.作業日)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.作業種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業開始時刻)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatTime(r.作業終了時刻)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatWorkTime(r.作業時間)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getInterruptionCount(r.作業記録ID || r.id)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${r.進捗状況 === '完了' ? 'rgba(34, 197, 94, 0.2)' : r.進捗状況 === '作業中' ? 'rgba(59, 130, 246, 0.2)' : 'rgba(239, 68, 68, 0.2)'}; color: var(--text);">
            ${r.進捗状況 || ""}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary detail-btn" data-id="${r.作業記録ID || r.id}" style="font-size: 11px; padding: 4px 8px;">詳細確認</button>
        </td>
      </tr>
    `).join("");
  }

  // 作業項目ドロップダウンを更新
  function updateWorkItemFilter() {
    const workItemSelect = container.querySelector("#filter-work-item");
    const uniqueWorkTypes = [...new Set(allWorkRecords.map(r => r.作業種別).filter(Boolean))];

    workItemSelect.innerHTML = '<option value="">すべて</option>' + 
      uniqueWorkTypes.map(type => `<option value="${type}">${type}</option>`).join("");
  }

  // フィルター適用関数
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    // バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return;
    }

    if (startDate && new Date(startDate) > new Date()) {
      showError("未来の日付は選択できません");
      return;
    }

    if (endDate && new Date(endDate) > new Date()) {
      showError("未来の日付は選択できません");
      return;
    }

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        showError("検索期間は1年以内で指定してください");
        return;
      }
    }

    if (!startDate && !endDate && !workItem && !status) {
      showError("日付範囲を選択してください");
      return;
    }

    let filteredRows = allWorkRecords;

    // 日付範囲フィルター
    if (startDate) {
      filteredRows = filteredRows.filter(r => {
        const workDate = new Date(r.作業日);
        return workDate >= new Date(startDate);
      });
    }

    if (endDate) {
      filteredRows = filteredRows.filter(r => {
        const workDate = new Date(r.作業日);
        return workDate <= new Date(endDate);
      });
    }

    // 作業項目フィルター
    if (workItem) {
      filteredRows = filteredRows.filter(r => r.作業種別 === workItem);
    }

    // 作業状況フィルター
    if (status) {
      filteredRows = filteredRows.filter(r => r.進捗状況 === status);
    }

    // 日付降順でソート
    filteredRows.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));

    renderRows(filteredRows);
  }

  // CSVエクスポート関数
  function exportCSV() {
    const headers = ["作業日時", "作業項目名", "開始時刻", "終了時刻", "作業時間", "中断回数", "進捗状況", "作業場所", "作業内容"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...allWorkRecords.map(r => [
        `"${formatDate(r.作業日)}"`,
        `"${r.作業種別 || ""}"`,
        `"${formatTime(r.作業開始時刻)}"`,
        `"${formatTime(r.作業終了時刻)}"`,
        `"${formatWorkTime(r.作業時間)}"`,
        `"${getInterruptionCount(r.作業記録ID || r.id)}"`,
        `"${r.進捗状況 || ""}"`,
        `"${r.作業場所 || ""}"`,
        `"${r.作業内容 || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録データを取得
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      allWorkRecords = workRecords || tables[1]?.records || [];

      // 中断記録データを取得
      const interruptions = await window.aivicApi.list(2); // 中断記録テーブル
      allInterruptions = interruptions || tables[2]?.records || [];

      // 作業項目マスタを取得
      const workItems = await window.aivicApi.list(3); // 作業項目マスタテーブル
      allWorkItems = workItems || tables[3]?.records || [];

      updateWorkItemFilter();

      // 日付降順でソート
      allWorkRecords.sort((a, b) => new Date(b.作業日) - new Date(a.作業日));

      renderRows(allWorkRecords);
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      // フォールバック: 初期データを使用
      allWorkRecords = tables[1]?.records || [];
      allInterruptions = tables[2]?.records || [];
      allWorkItems = tables[3]?.records || [];
      updateWorkItemFilter();
      renderRows(allWorkRecords);
    }
  }

  // イベントリスナー登録

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    renderRows(allWorkRecords);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 検索条件クリアボタン
  container.querySelector("#btn-clear-filters").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-work-item").value = "";
    container.querySelector("#filter-status").value = "";
    renderRows(allWorkRecords);
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // データ抽出ボタン
  container.querySelector("#btn-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  // 行レベル操作（詳細確認）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const recordId = detailBtn.dataset.id;
      // 詳細確認画面に遷移（レコードIDをパラメータとして渡す想定）
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentUser = { id: 'user-001', name: '田中太郎' };
  let activeWorks = [];
  let pausedWorks = [];
  let workItems = [];

  // 現在日時更新
  function updateCurrentDateTime() {
    const now = new Date();
    const dateTimeStr = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    container.querySelector('[data-testid="current-datetime"]').textContent = dateTimeStr;
  }

  // 経過時間計算
  function calculateElapsedTime(startTime) {
    const now = new Date();
    const start = new Date(startTime);
    const diffMs = now - start;
    const hours = Math.floor(diffMs / (1000 * 60 * 60));
    const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}時間${minutes}分`;
  }

  // 進行中作業一覧描画
  function renderActiveWorks() {
    const tbody = container.querySelector('#active-works-tbody');
    if (activeWorks.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">進行中の作業はありません</td></tr>';
      return;
    }

    tbody.innerHTML = activeWorks.map(work => {
      const startTime = new Date(work.作業開始時刻).toLocaleString('ja-JP', { 
        month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' 
      });
      const elapsed = calculateElapsedTime(work.作業開始時刻);
      return `
        <tr data-id="${work.作業記録ID}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${elapsed}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業場所 || ''}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary pause-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 12px;">中断</button>
            <button class="action-btn end-btn" data-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 12px; margin-left: 4px;">終了</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 中断中作業一覧描画
  function renderPausedWorks() {
    const tbody = container.querySelector('#paused-works-tbody');
    if (pausedWorks.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 12px;">中断中の作業はありません</td></tr>';
      return;
    }

    tbody.innerHTML = pausedWorks.map(work => {
      const pauseTime = new Date(work.中断開始日時).toLocaleString('ja-JP', { 
        month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' 
      });
      return `
        <tr data-id="${work.中断記録ID}">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${pauseTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.中断理由詳細 || work.中断理由区分 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${work.作業場所 || ''}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn resume-btn" data-id="${work.中断記録ID}" data-work-id="${work.作業記録ID}" style="padding: 4px 8px; font-size: 12px;">再開</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 作業項目選択肢描画
  function renderWorkItems() {
    const select = container.querySelector('#work-item-select');
    const currentOptions = select.innerHTML;
    const newOptions = '<option value="">作業項目を選択してください</option>' + 
      workItems.map(item => `<option value="${item.作業項目ID}">${item.作業項目名}</option>`).join('');
    if (currentOptions !== newOptions) {
      select.innerHTML = newOptions;
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 確認ダイアログ表示
  function showConfirm(title, message) {
    return new Promise((resolve) => {
      const dialog = container.querySelector('#confirm-dialog');
      container.querySelector('#confirm-title').textContent = title;
      container.querySelector('#confirm-message').textContent = message;
      dialog.classList.remove('hidden');

      const handleConfirm = (result) => {
        dialog.classList.add('hidden');
        container.querySelector('#confirm-ok').removeEventListener('click', okHandler);
        container.querySelector('#confirm-cancel').removeEventListener('click', cancelHandler);
        resolve(result);
      };

      const okHandler = () => handleConfirm(true);
      const cancelHandler = () => handleConfirm(false);

      container.querySelector('#confirm-ok').addEventListener('click', okHandler);
      container.querySelector('#confirm-cancel').addEventListener('click', cancelHandler);
    });
  }

  // データ読み込み
  async function loadData() {
    try {
      // 作業項目マスタ読み込み
      const workItemsData = await window.aivicApi.list(3);
      if (workItemsData) {
        workItems = workItemsData.filter(item => item.有効フラグ);
        renderWorkItems();
      }

      // 作業記録読み込み（進行中）
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) {
        activeWorks = workRecords.filter(record => 
          record.作業員ID === currentUser.id && 
          record.進捗状況 === '作業中' && 
          !record.作業終了時刻
        );
        renderActiveWorks();
      }

      // 中断記録読み込み
      const pauseRecords = await window.aivicApi.list(2);
      if (pauseRecords) {
        pausedWorks = pauseRecords.filter(record => 
          record.記録者ID === currentUser.id && 
          record.対応状況 === '対応中' && 
          !record.中断終了日時
        );
        renderPausedWorks();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 初期化
  updateCurrentDateTime();
  setInterval(updateCurrentDateTime, 60000); // 1分ごとに更新
  setInterval(() => {
    if (activeWorks.length > 0) {
      renderActiveWorks(); // 経過時間更新のため
    }
  }, 30000); // 30秒ごとに更新

  // 初期データ読み込み
  if (tables && tables.length > 0) {
    // 作業項目マスタ
    if (tables[3] && tables[3].records) {
      workItems = tables[3].records.filter(item => item.有効フラグ);
      renderWorkItems();
    }

    // 作業記録
    if (tables[1] && tables[1].records) {
      activeWorks = tables[1].records.filter(record => 
        record.作業員ID === currentUser.id && 
        record.進捗状況 === '作業中' && 
        !record.作業終了時刻
      );
      renderActiveWorks();
    }

    // 中断記録
    if (tables[2] && tables[2].records) {
      pausedWorks = tables[2].records.filter(record => 
        record.記録者ID === currentUser.id && 
        record.対応状況 === '対応中' && 
        !record.中断終了日時
      );
      renderPausedWorks();
    }
  }

  loadData();

  // 備考文字数カウンター
  const notesInput = container.querySelector('#work-notes-input');
  const notesCounter = container.querySelector('#notes-counter');
  notesInput.addEventListener('input', () => {
    notesCounter.textContent = notesInput.value.length;
  });

  // 作業開始ボタン
  container.querySelector('#btn-start-work').addEventListener('click', async () => {
    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location-input').value.trim();
    const workNotes = container.querySelector('#work-notes-input').value.trim();

    // バリデーション
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    // 複数作業同時開始制御
    if (activeWorks.length > 0) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return;
    }

    // 作業場所文字数チェック
    if (workLocation.length > 100) {
      showError('作業場所は100文字以内で入力してください');
      return;
    }

    // 備考文字数チェック
    if (workNotes.length > 500) {
      showError('備考は500文字以内で入力してください');
      return;
    }

    // 不正文字チェック
    if (/<script|javascript:|on\w+=/i.test(workLocation)) {
      showError('作業場所に不正な文字が含まれています');
      return;
    }

    const selectedWorkItem = workItems.find(item => item.作業項目ID === workItemId);
    if (!selectedWorkItem) {
      showError('選択された作業項目が見つかりません');
      return;
    }

    const now = new Date();
    const workRecord = {
      作業記録ID: `work-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      作業員ID: currentUser.id,
      作業日: now,
      作業開始時刻: now,
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: selectedWorkItem.作業項目名,
      作業場所: workLocation || null,
      作業種別: selectedWorkItem.カテゴリ || '一般作業',
      作業内容: selectedWorkItem.作業項目名,
      進捗状況: '作業中',
      備考: workNotes || null,
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成日時: now,
      更新日時: now,
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      // フォームクリア
      container.querySelector('#work-item-select').value = '';
      container.querySelector('#work-location-input').value = '';
      container.querySelector('#work-notes-input').value = '';
      notesCounter.textContent = '0';

      // データ再読み込み
      await loadData();

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");
    }
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#work-item-select').value = '';
    container.querySelector('#work-location-input').value = '';
    container.querySelector('#work-notes-input').value = '';
    notesCounter.textContent = '0';
  });

  // 設定ボタン
  container.querySelector('#btn-settings').addEventListener('click', () => {
    showError('設定機能は準備中です');
  });

  // ログアウトボタン
  container.querySelector('#btn-logout').addEventListener('click', async () => {
    const confirmed = await showConfirm('ログアウト', 'ログアウトしますか？');
    if (confirmed) {
      window.location.href = './login.html';
    }
  });

  // 作業操作（中断・終了・再開）
  container.addEventListener('click', async (e) => {
    // 中断ボタン
    const pauseBtn = e.target.closest('.pause-btn');
    if (pauseBtn) {
      const workId = pauseBtn.dataset.id;
      const confirmed = await showConfirm('作業中断', '作業を中断しますか？');
      if (confirmed) {
        const now = new Date();
        const pauseRecord = {
          中断記録ID: `pause-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          作業記録ID: workId,
          中断開始日時: now,
          中断終了日時: null,
          中断理由区分: '一時中断',
          中断理由詳細: '作業員による中断',
          中断時間: null,
          影響度: '軽微',
          対応状況: '対応中',
          記録者ID: currentUser.id,
          作成日時: now,
          更新日時: now
        };

        const saved = await window.aivicApi.save(2, pauseRecord);
        if (saved) {
          // 作業記録の進捗状況を更新
          await window.aivicApi.update(1, workId, { 進捗状況: '中断' });
          await loadData();
        }
      }
      return;
    }

    // 終了ボタン
    const endBtn = e.target.closest('.end-btn');
    if (endBtn) {
      const workId = endBtn.dataset.id;
      const confirmed = await showConfirm('作業終了', '作業を終了しますか？');
      if (confirmed) {
        const now = new Date();
        const work = activeWorks.find(w => w.作業記録ID === workId);
        if (work) {
          const startTime = new Date(work.作業開始時刻);
          const workTimeMinutes = Math.floor((now - startTime) / (1000 * 60));

          await window.aivicApi.update(1, workId, {
            作業終了時刻: now,
            作業時間: workTimeMinutes,
            進捗状況: '完了',
            更新日時: now
          });
          await loadData();
        }
      }
      return;
    }

    // 再開ボタン
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const pauseId = resumeBtn.dataset.id;
      const workId = resumeBtn.dataset.workId;

      // 複数作業同時開始制御
      if (activeWorks.length > 0) {
        showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
        return;
      }

      const confirmed = await showConfirm('作業再開', '中断中の作業を再開しますか？');
      if (confirmed) {
        const now = new Date();

        // 中断記録を終了
        const pauseWork = pausedWorks.find(p => p.中断記録ID === pauseId);
        if (pauseWork) {
          const pauseStartTime = new Date(pauseWork.中断開始日時);
          const pauseTimeMinutes = Math.floor((now - pauseStartTime) / (1000 * 60));

          await window.aivicApi.update(2, pauseId, {
            中断終了日時: now,
            中断時間: pauseTimeMinutes,
            対応状況: '解決済み',
            更新日時: now
          });
        }

        // 作業記録を再開状態に更新
        await window.aivicApi.update(1, workId, {
          進捗状況: '作業中',
          更新日時: now
        });

        await loadData();
      }
      return;
    }
  });
}

function(container, apiUrl, tables) {
  // 現在の作業記録データを取得（最新の未完了記録を想定）
  let currentWorkRecord = null;

  // 初期データの設定
  async function initializeData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords) {
        // 最新の未完了記録を取得
        currentWorkRecord = workRecords.find(r => r.作業終了時刻 && r.進捗状況 !== '完了') || 
                           workRecords[workRecords.length - 1] || 
                           tables[1].records[0];

        if (currentWorkRecord) {
          updateTimeDisplay();
        }
      }
    } catch (error) {
      console.error('データ初期化エラー:', error);
      // フォールバック: サンプルデータを使用
      currentWorkRecord = tables[1].records[0];
      updateTimeDisplay();
    }
  }

  // 時間表示の更新
  function updateTimeDisplay() {
    if (!currentWorkRecord) return;

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const endTime = currentWorkRecord.作業終了時刻? new Date(currentWorkRecord.作業終了時刻) : new Date();

    container.querySelector('#work-item-name').textContent = currentWorkRecord.作業内容 || 'システム保守作業';
    container.querySelector('#work-location').textContent = currentWorkRecord.作業場所 || 'データセンター A棟';
    container.querySelector('#start-time').textContent = formatTime(startTime);
    container.querySelector('#end-time').textContent = formatTime(endTime);

    // 作業時間計算
    const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));
    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    container.querySelector('#total-time').textContent = `${totalHours}:${totalMins.toString().padStart(2, '0')}`;

    // 中断時間を取得
    getBreakTime().then(breakMinutes => {
      const breakHours = Math.floor(breakMinutes / 60);
      const breakMins = breakMinutes % 60;
      container.querySelector('#break-time').textContent = `${breakHours}:${breakMins.toString().padStart(2, '0')}`;

      // 実作業時間計算
      const actualMinutes = totalMinutes - breakMinutes;
      const actualHours = Math.floor(actualMinutes / 60);
      const actualMins = actualMinutes % 60;
      container.querySelector('#actual-work-time').textContent = `${actualHours}:${actualMins.toString().padStart(2, '0')}`;
    });
  }

  // 時刻フォーマット
  function formatTime(date) {
    return `${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
  }

  // 中断時間を取得
  async function getBreakTime() {
    try {
      const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (breakRecords && currentWorkRecord) {
        const workBreaks = breakRecords.filter(b => b.作業記録ID === currentWorkRecord.作業記録ID);
        return workBreaks.reduce((total, b) => total + (b.中断時間 || 0), 0);
      }
    } catch (error) {
      console.error('中断時間取得エラー:', error);
    }
    return 60; // デフォルト値
  }

  // 文字数カウンター
  function setupCharacterCounter(inputId, counterId, maxLength) {
    const input = container.querySelector(`#${inputId}`);
    const counter = container.querySelector(`#${counterId}`);

    input.addEventListener('input', () => {
      const length = input.value.length;
      counter.textContent = length;

      if (length > maxLength) {
        counter.style.color = '#ff6a00';
      } else {
        counter.style.color = 'var(--text-muted)';
      }
    });
  }

  // 異常報告チェックボックスの制御
  function setupIssueToggle() {
    const hasIssueCheckbox = container.querySelector('#has-issue');
    const issueSection = container.querySelector('#issue-content-section');
    const issueContent = container.querySelector('#issue-content');

    hasIssueCheckbox.addEventListener('change', () => {
      if (hasIssueCheckbox.checked) {
        issueSection.style.display = 'block';
      } else {
        issueSection.style.display = 'none';
        issueContent.value = '';
        container.querySelector('#issue-count').textContent = '0';
      }
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value.trim();
    const workMemo = container.querySelector('#work-memo').value;

    if (!completionStatus) {
      showError('完了状況を選択してください。');
      return false;
    }

    if (hasIssue && !issueContent) {
      showError('異常報告をチェックした場合は、異常内容を入力してください。');
      return false;
    }

    if (workMemo.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    if (issueContent.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 記録確定処理
  async function confirmRecord() {
    if (!validateForm()) return;

    const workMemo = container.querySelector('#work-memo').value.trim();
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value.trim();

    try {
      // 作業記録を更新
      if (currentWorkRecord) {
        const updateData = {
          備考: workMemo,
          進捗状況: completionStatus,
          承認状態: '未承認',
          更新日時: new Date().toISOString()
        };

        const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

        if (updated) {
          // 異常報告がある場合は異常値検出ログに記録
          if (hasIssue && issueContent) {
            const anomalyData = {
              検出対象テーブル: '作業記録',
              検出対象レコードID: currentWorkRecord.作業記録ID,
              ユーザーID: currentWorkRecord.作業員ID,
              異常値種別: '作業異常報告',
              検出項目: '異常内容',
              検出値: issueContent,
              閾値: '手動報告',
              重要度: '中',
              確認状況: '未確認',
              通知送信フラグ: false,
              検出日時: new Date().toISOString(),
              作成日時: new Date().toISOString(),
              更新日時: new Date().toISOString()
            };

            await window.aivicApi.save(4, anomalyData);
          }

          alert('工数記録が正常に確定されました。');
          // 前画面に戻る（工数記録画面など）
          history.back();
        } else {
          showError('記録の保存に失敗しました。');
        }
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
      showError('記録の保存中にエラーが発生しました。');
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 文字数カウンター
    setupCharacterCounter('work-memo', 'memo-count', 1000);
    setupCharacterCounter('issue-content', 'issue-count', 500);

    // 異常報告トグル
    setupIssueToggle();

    // ボタンイベント
    container.querySelector('#btn-confirm').addEventListener('click', confirmRecord);

    container.querySelector('#btn-cancel').addEventListener('click', () => {
      if (confirm('入力内容が破棄されますが、よろしいですか？')) {
        history.back();
      }
    });

    container.querySelector('#btn-check-record').addEventListener('click', () => {
      window.showScreen("scr-1778907226171");
    });

    // ホバーエフェクト
    const buttons = container.querySelectorAll('button');
    buttons.forEach(btn => {
      btn.addEventListener('mouseenter', () => {
        if (btn.id === 'btn-confirm') {
          btn.style.background = 'var(--primary-hover)';
        } else {
          btn.style.background = 'rgba(255,255,255,0.05)';
        }
      });

      btn.addEventListener('mouseleave', () => {
        if (btn.id === 'btn-confirm') {
          btn.style.background = 'var(--primary)';
        } else {
          btn.style.background = 'transparent';
        }
      });
    });
  }

  // 初期化実行
  initializeData();
  setupEventListeners();
}

function(container, apiUrl, tables) {
  let autoSaveInterval = 30; // デフォルト30秒
  let autoSaveTimer = null;
  let isOnline = navigator.onLine;
  let localData = JSON.parse(localStorage.getItem('workRecords') || '[]');
  let pendingSyncCount = localData.filter(item => !item.synced).length;

  // ローカルデータ再描画関数
  function renderLocalData() {
    const tbody = container.querySelector('#local-data-tbody');
    if (localData.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 13px;">ローカルデータはありません</td></tr>';
      return;
    }

    tbody.innerHTML = localData.map(item => `
      <tr data-id="${item.id}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${item.作業日 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${(item.作業内容 || '').substring(0, 30)}${(item.作業内容 || '').length > 30 ? '...' : ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="color: ${item.synced ? '#22c55e' : '#f59e0b'};">
            ${item.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary delete-local-btn" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ステータス更新
  function updateStatus() {
    const autoSaveIndicator = container.querySelector('#auto-save-indicator');
    const autoSaveStatus = container.querySelector('#auto-save-status');
    const networkIndicator = container.querySelector('#network-indicator');
    const networkStatus = container.querySelector('#network-status');
    const pendingSyncCountEl = container.querySelector('#pending-sync-count');

    // 自動保存ステータス
    autoSaveIndicator.style.background = autoSaveTimer ? '#22c55e' : '#ef4444';
    autoSaveStatus.textContent = autoSaveTimer ? '正常動作中' : '停止中';

    // ネットワークステータス
    networkIndicator.style.background = isOnline ? '#22c55e' : '#ef4444';
    networkStatus.textContent = isOnline ? 'オンライン' : 'オフライン';

    // 同期待ち件数
    pendingSyncCount = localData.filter(item => !item.synced).length;
    pendingSyncCountEl.textContent = pendingSyncCount;
  }

  // エラー表示
  function showError(message) {
    const errorNotification = container.querySelector('#error-notification');
    const errorMessage = container.querySelector('#error-message');
    errorMessage.textContent = message;
    errorNotification.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    const errorNotification = container.querySelector('#error-notification');
    errorNotification.style.display = 'none';
  }

  // 自動保存開始
  function startAutoSave() {
    if (autoSaveTimer) clearInterval(autoSaveTimer);

    if (autoSaveInterval < 1) {
      showError('保存間隔は1秒以上で設定してください');
      return;
    }

    autoSaveTimer = setInterval(async () => {
      try {
        // 未同期データがあれば同期を試行
        const unsyncedData = localData.filter(item => !item.synced);
        if (unsyncedData.length > 0 && isOnline) {
          await syncData();
        }

        // 最終保存時刻更新
        const lastSaveTime = container.querySelector('#last-save-time');
        lastSaveTime.textContent = new Date().toLocaleString('ja-JP');

        hideError();
      } catch (error) {
        showError('自動保存中にエラーが発生しました: ' + error.message);
      }
    }, autoSaveInterval * 1000);

    updateStatus();
  }

  // データ同期
  async function syncData() {
    const unsyncedData = localData.filter(item => !item.synced);

    for (const item of unsyncedData) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: item.作業員ID,
          作業日: item.作業日,
          作業開始時刻: item.作業開始時刻,
          作業終了時刻: item.作業終了時刻,
          作業時間: item.作業時間,
          プロジェクト名: item.プロジェクト名,
          作業場所: item.作業場所,
          作業種別: item.作業種別,
          作業内容: item.作業内容,
          進捗状況: item.進捗状況,
          備考: item.備考,
          承認状態: '未承認',
          作成者ID: item.作業員ID
        });

        if (saved) {
          // 同期成功
          item.synced = true;
          item.serverId = saved.作業記録ID;
        }
      } catch (error) {
        console.error('同期エラー:', error);
        throw error;
      }
    }

    // ローカルストレージ更新
    localStorage.setItem('workRecords', JSON.stringify(localData));
    renderLocalData();
    updateStatus();
  }

  // 手動同期
  async function manualSync() {
    try {
      if (!isOnline) {
        showError('ネットワークに接続されていません');
        return;
      }

      await syncData();
      hideError();

      // 成功通知（簡易版）
      const btn = container.querySelector('#btn-manual-sync');
      const originalText = btn.textContent;
      btn.textContent = '同期完了';
      btn.style.background = '#22c55e';
      setTimeout(() => {
        btn.textContent = originalText;
        btn.style.background = 'transparent';
      }, 2000);

    } catch (error) {
      showError('同期に失敗しました: ' + error.message);
    }
  }

  // データ復旧チェック
  function checkRecovery() {
    const recoveryData = localStorage.getItem('unsavedWorkData');
    if (recoveryData) {
      const recoverySection = container.querySelector('#recovery-section');
      recoverySection.style.display = 'block';
    }
  }

  // ネットワーク状態監視
  window.addEventListener('online', () => {
    isOnline = true;
    updateStatus();
    // オンライン復旧時の自動同期
    if (pendingSyncCount > 0) {
      setTimeout(() => {
        syncData().catch(error => {
          showError('自動同期に失敗しました: ' + error.message);
        });
      }, 1000);
    }
  });

  window.addEventListener('offline', () => {
    isOnline = false;
    updateStatus();
  });

  // 初期データ表示
  renderLocalData();
  updateStatus();
  checkRecovery();

  // 保存間隔設定の初期値
  const saveIntervalInput = container.querySelector('#save-interval');
  saveIntervalInput.value = autoSaveInterval;

  // 自動保存開始
  startAutoSave();

  // イベントリスナー登録

  // 設定保存
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const newInterval = parseInt(saveIntervalInput.value);

    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください');
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒以下で設定してください');
      return;
    }

    autoSaveInterval = newInterval;
    localStorage.setItem('autoSaveInterval', autoSaveInterval.toString());
    startAutoSave();
    hideError();

    // 成功通知
    const btn = container.querySelector('#btn-save-settings');
    const originalText = btn.textContent;
    btn.textContent = '保存完了';
    setTimeout(() => {
      btn.textContent = originalText;
    }, 1500);
  });

  // 手動同期
  container.querySelector('#btn-manual-sync').addEventListener('click', manualSync);

  // 再試行
  container.querySelector('#btn-retry').addEventListener('click', () => {
    hideError();
    manualSync();
  });

  // ローカルデータクリア
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (!confirm('ローカルデータをすべて削除しますか？未同期のデータは失われます。')) return;

    localStorage.removeItem('workRecords');
    localData = [];
    renderLocalData();
    updateStatus();
  });

  // データ復旧
  container.querySelector('#btn-recover')?.addEventListener('click', () => {
    const recoveryData = localStorage.getItem('unsavedWorkData');
    if (recoveryData) {
      try {
        const data = JSON.parse(recoveryData);
        localData.push({
          id: Date.now().toString(),
          ...data,
          synced: false
        });
        localStorage.setItem('workRecords', JSON.stringify(localData));
        localStorage.removeItem('unsavedWorkData');
        renderLocalData();
        updateStatus();
        container.querySelector('#recovery-section').style.display = 'none';
      } catch (error) {
        showError('データ復旧に失敗しました');
      }
    }
  });

  // データ破棄
  container.querySelector('#btn-discard')?.addEventListener('click', () => {
    localStorage.removeItem('unsavedWorkData');
    container.querySelector('#recovery-section').style.display = 'none';
  });

  // ローカルデータ削除（イベントデリゲーション）
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      if (!confirm('このローカルデータを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      localData = localData.filter(item => item.id !== id);
      localStorage.setItem('workRecords', JSON.stringify(localData));
      renderLocalData();
      updateStatus();
    }
  });

  // 保存間隔の設定値を復元
  const savedInterval = localStorage.getItem('autoSaveInterval');
  if (savedInterval) {
    autoSaveInterval = parseInt(savedInterval);
    saveIntervalInput.value = autoSaveInterval;
    startAutoSave();
  }
}

function(container, apiUrl, tables) {
  let currentRecords = [];
  let deleteTargetId = null;

  // 時刻フォーマット関数
  function formatTime(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const date = new Date(timestamp);
    return date.toLocaleDateString('ja-JP');
  }

  // 作業時間計算（分）
  function calculateWorkTime(start, end) {
    if (!start || !end) return 0;
    return Math.floor((new Date(end) - new Date(start)) / (1000 * 60));
  }

  // 時間フォーマット（分 → H時間M分）
  function formatDuration(minutes) {
    if (!minutes || minutes === 0) return '0分';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}分`;
    if (mins === 0) return `${hours}時間`;
    return `${hours}時間${mins}分`;
  }

  // 異常値チェック
  function hasAnomalies(record) {
    const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
    const breakTime = record.中断時間 || 0;

    // 24時間超過、中断時間が作業時間を超過、終了時刻が開始時刻より早い
    return workTime > 1440 || breakTime > workTime || 
           (record.作業開始時刻&& record.作業終了時刻 && new Date(record.作業終了時刻) < new Date(record.作業開始時刻));
  }

  // 作業項目名取得
  function getWorkItemName(workItemId) {
    if (!workItemId) return '-';
    const workItemTable = tables[3]; // 作業項目マスタ
    const workItem = workItemTable?.records?.find(item => item.作業項目ID === workItemId);
    return workItem ? workItem.作業項目名 : workItemId;
  }

  // 承認状態の表示
  function getApprovalStatusBadge(status) {
    const statusMap = {
      '未承認': { text: '未承認', color: '#ffc107', bg: 'rgba(255, 193, 7, 0.1)' },
      '承認済み': { text: '承認済み', color: '#28a745', bg: 'rgba(40, 167, 69, 0.1)' },
      '差し戻し': { text: '差し戻し', color: '#dc3545', bg: 'rgba(220, 53, 69, 0.1)' }
    };
    const config = statusMap[status] || { text: status || '-', color: 'var(--text-muted)', bg: 'transparent' };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${config.bg}; color: ${config.color};">${config.text}</span>`;
  }

  // 権限チェック
  function canEdit(record) {
    return record.承認状態 !== '承認済み';
  }

  function canDelete(record) {
    return record.承認状態 !== '承認済み';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#records-tbody');
    const emptyMessage = container.querySelector('#empty-message');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.classList.remove('hidden');
      return;
