      const hasAnomaly = hasAnomalies(record);
      const workItemName = getWorkItemName(record.プロジェクト名); // プロジェクト名を作業項目として表示

      return `
        <tr data-id="${record.作業記録ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.プロジェクト名 || '-'}</td>
