        </div>
        <div>
          <label style="font-size: 11px; color: var(--text-muted); display: block; margin-bottom: 4px;">進捗状況</label>
          <div style="font-size: 13px; color: var(--text); padding: 6px 0;">${record.進捗状況 || '-'}</div>
        </div>
      </div>
    `;

    container.querySelector('#detail-modal').classList.remove('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentRecords || currentRecords.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['作業日', '作業項目', '開始時刻', '終了時刻', '作業時間', '中断時間', '作業場所', '作業内容', '備考', '承認状態'];
    const csvData = [headers.join(',')];

    currentRecords.forEach(record => {
      const workTime = calculateWorkTime(record.作業開始時刻, record.作業終了時刻);
      const breakTime = record.中断時間 || 0;

      const row = [
        formatDate(record.作業日),
        record.プロジェクト名 || '',
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        formatDuration(workTime),
        formatDuration(breakTime),
        record.作業場所 || '',
        (record.作業内容 || '').replace(/"/g, '""'),
        (record.備考 || '').replace(/"/g, '""'),
        record.承認状態 || ''
      ].map(field => `"${field}"`);

      csvData.push(row.join(','));
    });

    const csvContent = '\uFEFF' + csvData.join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `work_records_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // フィルタリング
  function applyFilters() {
    const dateFilter = container.querySelector('#date-filter').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    window.aivicApi.list(1).then(rows => {
      if (!rows) return;

      let filtered = rows;

      // 単一日付フィルタ
      if (dateFilter) {
        filtered = filtered.filter(record => {
          const recordDate = new Date(record.作業日).toISOString().split('T')[0];
          return recordDate === dateFilter;
        });
      }

      // 期間フィルタ
      if (startDate || endDate) {
        filtered = filtered.filter(record => {
          const recordDate = new Date(record.作業日);
          let inRange = true;

          if (startDate) {
            inRange = inRange && recordDate >= new Date(startDate);
          }
          if (endDate) {
            inRange = inRange && recordDate <= new Date(endDate);
          }

          return inRange;
        });
      }

      currentRecords = filtered;
      renderRows(filtered);
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      currentRecords = rows;
      renderRows(rows);
    }
  });

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#date-filter').value = today;

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-back-menu').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 詳細モーダル関連
  container.querySelector('#close-detail').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // 削除確認モーダル関連
  container.querySelector('#cancel-delete').addEventListener('click', () => {
    container.querySelector('#delete-modal').classList.add('hidden');
    deleteTargetId = null;
  });

  container.querySelector('#confirm-delete').addEventListener('click', async () => {
    if (deleteTargetId) {
      const result = await window.aivicApi.delete(1, deleteTargetId);
      if (result !== null) {
        container.querySelector('#delete-modal').classList.add('hidden');
        deleteTargetId = null;
        // データ再読み込み
        window.aivicApi.list(1).then(rows => {
          if (rows) {
            currentRecords = rows;
            renderRows(rows);
          }
        });
      }
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細表示
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 編集
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      window.showScreen('scr-1778907343735');
      return;
    }

    // 削除
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      deleteTargetId = deleteBtn.dataset.id;
      container.querySelector('#delete-modal').classList.remove('hidden');
      return;
    }
  });

  // 日付フィルタの変更時に自動適用
  container.querySelector('#date-filter').addEventListener('change', applyFilters);
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let recordedBlob = null;

  // DOM要素の取得
  const startTimeInput = container.querySelector('#start-time');
  const endTimeInput = container.querySelector('#end-time');
  const reasonSelect = container.querySelector('#reason');
  const locationInput = container.querySelector('#location');
  const detailsTextarea = container.querySelector('#details');
  const charCount = container.querySelector('#char-count');
  const durationDisplay = container.querySelector('#duration-display');
  const workItemDisplay = container.querySelector('#work-item-display');
  const photoUpload = container.querySelector('#photo-upload');
  const photoBtn = container.querySelector('#photo-btn');
  const photoPreview = container.querySelector('#photo-preview');
  const recordBtn = container.querySelector('#record-btn');
  const stopBtn = container.querySelector('#stop-btn');
  const recordingStatus = container.querySelector('#recording-status');
  const audioPlayback = container.querySelector('#audio-playback');
  const selectAllImpact = container.querySelector('#select-all-impact');
  const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
  const tempSaveBtn = container.querySelector('#btn-temp-save');
  const completeBtn = container.querySelector('#btn-complete');
  const errorMessage = container.querySelector('#error-message');
  const successMessage = container.querySelector('#success-message');

  // 初期化
  function init() {
    // 現在時刻を中断開始時刻にセット
    const now = new Date();
    startTimeInput.value = now.toISOString().slice(0, 16);

    // 関連作業項目の表示（現在進行中の作業を表示）
    loadCurrentWorkItem();

    // 一時保存データの復元
    loadTempData();

    // 中断時間の計算
    updateDuration();
  }

  // 現在の作業項目を読み込み
  async function loadCurrentWorkItem() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords) {
        const currentWork = workRecords.find(record => record.進捗状況 === '作業中');
        if (currentWork) {
          workItemDisplay.textContent = `${currentWork.プロジェクト名} - ${currentWork.作業種別}`;
          workItemDisplay.dataset.workRecordId = currentWork.作業記録ID;
        } else {
          workItemDisplay.textContent = '進行中の作業項目がありません';
        }
      }
    } catch (error) {
      workItemDisplay.textContent = '作業項目の読み込みに失敗しました';
    }
  }

  // 文字数カウント
  detailsTextarea.addEventListener('input', () => {
    const count = detailsTextarea.value.length;
    charCount.textContent = count;
    if (count > 1000) {
      charCount.style.color = '#fca5a5';
    } else {
      charCount.style.color = 'var(--text-muted)';
    }
  });

  // 中断時間の自動計算
  function updateDuration() {
    const startTime = startTimeInput.value;
    const endTime = endTimeInput.value;

    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      const diffMs = end - start;

      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        durationDisplay.textContent = `${hours}時間${minutes}分`;
        durationDisplay.style.color = 'var(--text)';
      } else {
        durationDisplay.textContent = '終了時刻が開始時刻より前です';
        durationDisplay.style.color = '#fca5a5';
      }
    } else if (startTime) {
      durationDisplay.textContent = '終了時刻を入力してください';
      durationDisplay.style.color = 'var(--text-muted)';
    } else {
      durationDisplay.textContent = '自動計算されます';
      durationDisplay.style.color = 'var(--text-muted)';
    }
  }

  startTimeInput.addEventListener('change', updateDuration);
  endTimeInput.addEventListener('change', updateDuration);

  // 写真アップロード
  photoBtn.addEventListener('click', () => {
    photoUpload.click();
  });

  photoUpload.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 0) {
      // ファイル形式チェック
      const invalidFiles = files.filter(file => !file.type.startsWith('image/'));
      if (invalidFiles.length > 0) {
        showError('対応していないファイル形式が含まれています。画像ファイルのみ選択してください。');
        return;
      }

      // ファイルサイズチェック（10MB制限）
      const oversizeFiles = files.filter(file => file.size > 10 * 1024 * 1024);
      if (oversizeFiles.length > 0) {
        showError('ファイルサイズが上限（10MB）を超えています。');
        return;
      }

      photoPreview.textContent = `${files.length}個のファイルが選択されました`;
    } else {
      photoPreview.textContent = '';
    }
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorder = new MediaRecorder(stream);
      audioChunks = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunks.push(event.data);
      };

      mediaRecorder.onstop = () => {
        recordedBlob = new Blob(audioChunks, { type: 'audio/wav' });
        audioPlayback.src = URL.createObjectURL(recordedBlob);
        audioPlayback.style.display = 'block';
        recordingStatus.textContent = '録音完了 - 再生して確認できます';
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      recordBtn.disabled = true;
      stopBtn.disabled = false;
      recordingStatus.textContent = '録音中...';
    } catch (error) {
      showError('マイクへのアクセスが拒否されました。録音機能を使用するにはマイクの許可が必要です。');
    }
  });

  stopBtn.addEventListener('click', () => {
    if (mediaRecorder && mediaRecorder.state === 'recording') {
      mediaRecorder.stop();
      recordBtn.disabled = false;
      stopBtn.disabled = true;
    }
  });

  // 影響範囲の全選択・全解除
  selectAllImpact.addEventListener('change', () => {
    impactCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllImpact.checked;
    });
  });

  // 個別選択時の全選択チェックボックス連動
  impactCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      const checkedCount = Array.from(impactCheckboxes).filter(cb => cb.checked).length;
      selectAllImpact.checked = checkedCount === impactCheckboxes.length;
      selectAllImpact.indeterminate = checkedCount > 0 && checkedCount < impactCheckboxes.length;
    });
  });

  // バリデーション
  function validateForm() {
    const errors = [];

    // 必須項目チェック
    if (!startTimeInput.value) {
      errors.push('中断開始時刻は必須です');
    }
    if (!reasonSelect.value) {
      errors.push('中断理由は必須です');
    }

    // 未来時刻チェック
    if (startTimeInput.value) {
      const startTime = new Date(startTimeInput.value);
      const now = new Date();
      if (startTime > now) {
        errors.push('中断開始時刻に未来の時刻は入力できません');
      }
    }

    if (endTimeInput.value) {
      const endTime = new Date(endTimeInput.value);
      const now = new Date();
      if (endTime > now) {
        errors.push('中断終了時刻に未来の時刻は入力できません');
      }
    }

    // 時刻の前後関係チェック
    if (startTimeInput.value && endTimeInput.value) {
      const start = new Date(startTimeInput.value);
      const end = new Date(endTimeInput.value);
      if (end <= start) {
        errors.push('中断終了時刻は開始時刻より後の時刻を入力してください');
      }
    }

    // 文字数チェック
    if (detailsTextarea.value.length > 1000) {
      errors.push('中断詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    successMessage.style.display = 'none';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    successMessage.textContent = message;
    successMessage.style.display = 'block';
    errorMessage.style.display = 'none';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 3000);
  }

  // フォームデータ収集
  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const impactValues = Array.from(container.querySelectorAll('input[name="impact"]:checked')).map(cb => cb.value);

    let durationMinutes = null;
    if (startTimeInput.value && endTimeInput.value) {
      const start = new Date(startTimeInput.value);
      const end = new Date(endTimeInput.value);
      durationMinutes = Math.floor((end - start) / (1000 * 60));
    }

    return {
      作業記録ID: workItemDisplay.dataset.workRecordId || null,
      中断開始日時: startTimeInput.value ? new Date(startTimeInput.value).toISOString() : null,
      中断終了日時: endTimeInput.value ? new Date(endTimeInput.value).toISOString() : null,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value,
      中断時間: durationMinutes,
      影響度: urgencyRadio ? urgencyRadio.value : '中',
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では認証されたユーザーIDを使用
      中断場所: locationInput.value,
      影響範囲: impactValues.join(', '),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 一時保存
  tempSaveBtn.addEventListener('click', () => {
    const formData = collectFormData();
    localStorage.setItem('interruption_temp_data', JSON.stringify(formData));
    showSuccess('一時保存しました');
  });

  // 一時保存データの読み込み
  function loadTempData() {
    const tempData = localStorage.getItem('interruption_temp_data');
    if (tempData) {
      try {
        const data = JSON.parse(tempData);
        if (data.中断開始日時) startTimeInput.value = new Date(data.中断開始日時).toISOString().slice(0, 16);
        if (data.中断終了日時) endTimeInput.value = new Date(data.中断終了日時).toISOString().slice(0, 16);
        if (data.中断理由区分) reasonSelect.value = data.中断理由区分;
        if (data.中断理由詳細) detailsTextarea.value = data.中断理由詳細;
        if (data.中断場所) locationInput.value = data.中断場所;
        if (data.影響度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }
        updateDuration();
        detailsTextarea.dispatchEvent(new Event('input'));
      } catch (error) {
        console.error('一時保存データの読み込みに失敗しました:', error);
      }
    }
  }

  // 記録完了
  completeBtn.addEventListener('click', async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('、'));
      return;
    }

    try {
      const formData = collectFormData();
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル

      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('interruption_temp_data');
        showSuccess('中断記録を保存しました');

        // 2秒後に作業再開記録画面に遷移
        setTimeout(() => {
          window.showScreen("scr-1778907251446");
        }, 2000);
      } else {
        showError('保存に失敗しました。ネットワーク接続を確認してください。');
      }
    } catch (error) {
      showError('保存中にエラーが発生しました: ' + error.message);
    }
  });

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedInterruptRecord = null;

  // DOM要素の取得
  const suspendedWorkTbody = container.querySelector('#suspended-work-tbody');
  const noSuspendedWork = container.querySelector('#no-suspended-work');
  const resumeForm = container.querySelector('#resume-form');
  const resumeTimeInput = container.querySelector('#resume-time');
  const resumeReasonSelect = container.querySelector('#resume-reason-select');
  const resumeReasonDetail = container.querySelector('#resume-reason-detail');
  const charCount = container.querySelector('#char-count');
  const resumeReasonError = container.querySelector('#resume-reason-error');
  const confirmDialog = container.querySelector('#resume-confirm-dialog');

  // 中断中作業一覧の描画
  function renderSuspendedWorks() {
    // 作業記録テーブル（tableIndex: 1）と中断記録テーブル（tableIndex: 2）を取得
    Promise.all([
      window.aivicApi.list(1), // 作業記録
      window.aivicApi.list(2)  // 中断記録
    ]).then(([workRecords, interruptRecords]) => {
      if (!workRecords || !interruptRecords) return;

      // 中断中の作業を抽出（進捗状況が「中断」で、対応する中断記録の終了日時がnull）
      const suspendedWorks = workRecords.filter(work => 
        work.進捗状況 === '中断'
      ).map(work => {
        const interrupt = interruptRecords.find(int => 
          int.作業記録ID === work.作業記録ID && !int.中断終了日時
        );
        return { work, interrupt };
      }).filter(item => item.interrupt);

      if (suspendedWorks.length === 0) {
        suspendedWorkTbody.innerHTML = '';
        noSuspendedWork.classList.remove('hidden');
        resumeForm.classList.add('hidden');
        return;
      }

      noSuspendedWork.classList.add('hidden');

      suspendedWorkTbody.innerHTML = suspendedWorks.map(({ work, interrupt }) => `
        <tr data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt.中断記録ID}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px;">${work.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${interrupt.中断開始日時 ? new Date(interrupt.中断開始日時).toLocaleString() : ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${interrupt.中断理由詳細 || interrupt.中断理由区分 || ''}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn select-work-btn" data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt.中断記録ID}" style="padding: 4px 8px; font-size: 12px;">選択</button>
          </td>
        </tr>
      `).join('');
    });
  }

  // 作業選択時の処理
  function selectWork(workId, interruptId) {
    Promise.all([
      window.aivicApi.list(1), // 作業記録
      window.aivicApi.list(2)  // 中断記録
    ]).then(([workRecords, interruptRecords]) => {
      if (!workRecords || !interruptRecords) return;

      selectedWorkRecord = workRecords.find(w => w.作業記録ID === workId);
      selectedInterruptRecord = interruptRecords.find(i => i.中断記録ID === interruptId);

      if (!selectedWorkRecord || !selectedInterruptRecord) return;

      // 選択された作業の詳細を表示
      container.querySelector('#selected-work-name').textContent = selectedWorkRecord.作業内容 || '';
      container.querySelector('#selected-suspend-time').textContent = selectedInterruptRecord.中断開始日時 ? 
        new Date(selectedInterruptRecord.中断開始日時).toLocaleString() : '';
      container.querySelector('#selected-suspend-reason').textContent = selectedInterruptRecord.中断理由詳細 || selectedInterruptRecord.中断理由区分 || '';

      // 再開時刻を現在時刻に設定
      const now = new Date();
      const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
      resumeTimeInput.value = localDateTime;

      // フォームをクリア
      resumeReasonSelect.value = '';
      resumeReasonDetail.value = '';
      charCount.textContent = '0';
      resumeReasonError.classList.add('hidden');

      resumeForm.classList.remove('hidden');
    });
  }

  // 文字数カウント
  resumeReasonDetail.addEventListener('input', () => {
    const length = resumeReasonDetail.value.length;
    charCount.textContent = length;

    if (length > 500) {
      resumeReasonError.textContent = '再開理由は500文字以内で入力してください';
      resumeReasonError.classList.remove('hidden');
    } else {
      resumeReasonError.classList.add('hidden');
    }
  });

  // 再開理由選択時の処理
  resumeReasonSelect.addEventListener('change', () => {
    if (resumeReasonSelect.value && resumeReasonSelect.value !== 'その他') {
      resumeReasonDetail.value = resumeReasonSelect.value;
      charCount.textContent = resumeReasonDetail.value.length;
    }
  });

  // バリデーション
  function validateForm() {
    const reasonDetail = resumeReasonDetail.value.trim();

    if (!reasonDetail) {
      resumeReasonError.textContent = '再開理由は必須です';
      resumeReasonError.classList.remove('hidden');
      return false;
    }

    if (reasonDetail.length > 500) {
      resumeReasonError.textContent = '再開理由は500文字以内で入力してください';
      resumeReasonError.classList.remove('hidden');
      return false;
    }

    resumeReasonError.classList.add('hidden');
    return true;
  }

  // 作業再開処理
  function resumeWork() {
    if (!selectedWorkRecord || !selectedInterruptRecord) return;

    const resumeTime = new Date(resumeTimeInput.value).toISOString();

    // 中断記録を更新（終了日時を設定）
    window.aivicApi.update(2, selectedInterruptRecord.中断記録ID, {
      中断終了日時: resumeTime
    }).then(updatedInterrupt => {
      if (!updatedInterrupt) return;

      // 作業記録を更新（進捗状況を「作業中」に変更）
      return window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中'
      });
    }).then(updatedWork => {
      if (!updatedWork) return;

      // 成功メッセージ表示
      alert('作業を再開しました');

      // フォームをリセット
      resumeForm.classList.add('hidden');
      selectedWorkRecord = null;
      selectedInterruptRecord = null;

      // 一覧を再描画
      renderSuspendedWorks();

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");
    });
  }

  // イベントリスナー
  container.addEventListener('click', (e) => {
    // 作業選択
    const selectBtn = e.target.closest('.select-work-btn');
    if (selectBtn) {
      const workId = selectBtn.dataset.workId;
      const interruptId = selectBtn.dataset.interruptId;
      selectWork(workId, interruptId);
      return;
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    history.back();
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    resumeForm.classList.add('hidden');
    selectedWorkRecord = null;
    selectedInterruptRecord = null;
  });

  // 作業再開ボタン
  container.querySelector('#btn-resume').addEventListener('click', () => {
    if (!validateForm()) return;
    confirmDialog.classList.remove('hidden');
  });

  // 確認ダイアログのキャンセル
  container.querySelector('#btn-dialog-cancel').addEventListener('click', () => {
    confirmDialog.classList.add('hidden');
  });

  // 確認ダイアログのOK
  container.querySelector('#btn-dialog-ok').addEventListener('click', () => {
    confirmDialog.classList.add('hidden');
    resumeWork();
  });

  // 初期データ読み込み
  renderSuspendedWorks();
}

function(container, apiUrl, tables) {
  let currentErrors = [];
  let existingRecords = [];

  // 既存レコードを取得
  async function loadExistingRecords() {
    try {
      existingRecords = await window.aivicApi.list(1) || []; // 作業記録テーブル
    } catch (error) {
      existingRecords = tables[1]?.records || [];
    }
  }

  // 入力チェック実行
  function performValidation() {
    currentErrors = [];
    const workDate = container.querySelector('#work-date').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;
    const workContent = container.querySelector('#work-content').value;
    const workLocation = container.querySelector('#work-location').value;
    const workerName = container.querySelector('#worker-name').value;

    // 必須項目チェック
    const requiredErrors = [];
    if (!workDate) requiredErrors.push('作業日は必須です');
    if (!workContent) requiredErrors.push('作業内容は必須です');
    if (!startTime) requiredErrors.push('作業開始時刻は必須です');
    if (!endTime) requiredErrors.push('作業終了時刻は必須です');
    if (!workLocation) requiredErrors.push('作業場所は必須です');
    if (!workerName) requiredErrors.push('担当者名は必須です');

    updateCheckStatus('required', requiredErrors);

    // 入力形式チェック
    const formatErrors = [];
    if (workDate && !isValidDate(workDate)) formatErrors.push('作業日の形式が正しくありません');
    if (startTime && !isValidTime(startTime)) formatErrors.push('開始時刻の形式が正しくありません');
    if (endTime && !isValidTime(endTime)) formatErrors.push('終了時刻の形式が正しくありません');
    if (breakTime && (isNaN(breakTime) || breakTime < 0)) formatErrors.push('休憩時間は正の値で入力してください');
    if (workContent && workContent.length > 200) formatErrors.push('作業内容は200文字以内で入力してください');

    updateCheckStatus('format', formatErrors);

    // 日時整合性チェック
    const datetimeErrors = [];
    if (workDate && startTime && endTime) {
      const startDateTime = new Date(`${workDate}T${startTime}`);
      const endDateTime = new Date(`${workDate}T${endTime}`);
      if (startDateTime >= endDateTime) {
        datetimeErrors.push('開始時刻は終了時刻より前に設定してください');
      }
    }

    updateCheckStatus('datetime', datetimeErrors);

    // 作業時間妥当性チェック
    const worktimeErrors = [];
    if (workDate && startTime && endTime) {
      const startDateTime = new Date(`${workDate}T${startTime}`);
      const endDateTime = new Date(`${workDate}T${endTime}`);
      const workMinutes = (endDateTime - startDateTime) / (1000 * 60);
      const breakMinutes = parseInt(breakTime) || 0;
      const actualWorkMinutes = workMinutes - breakMinutes;

      if (actualWorkMinutes <= 0) {
        worktimeErrors.push('実作業時間が0分以下です');
      } else if (actualWorkMinutes < 5) {
        worktimeErrors.push('作業時間が異常に短く設定されています。確認してください。');
      } else if (actualWorkMinutes > 1440) { // 24時間
        worktimeErrors.push('24時間を超過する作業時間が入力されました');
      } else if (actualWorkMinutes > 720) { // 12時間
        worktimeErrors.push('作業時間が異常に長く設定されています。確認してください。');
      }
    }

    updateCheckStatus('worktime', worktimeErrors);

    // 重複データチェック
    const duplicateErrors = [];
    if (workDate && startTime) {
      const targetDateTime = `${workDate}T${startTime}`;
      const duplicate = existingRecords.find(record => {
        const recordDateTime = record.作業開始時刻 || record.workStartTime;
        return recordDateTime && recordDateTime.includes(workDate) && recordDateTime.includes(startTime);
      });
      if (duplicate) {
        duplicateErrors.push('指定された日時には既に作業記録が登録されています。別の日時を指定してください。');
      }
    }

    updateCheckStatus('duplicate', duplicateErrors);

    // 異常値検出
    const anomalyErrors = [];
    if (workContent && /^[0-9\s\-_]+$/.test(workContent)) {
      anomalyErrors.push('作業内容に数値や記号のみが入力されています');
    }
    if (workerName && /^[0-9\s\-_]+$/.test(workerName)) {
      anomalyErrors.push('担当者名に数値や記号のみが入力されています');
    }

    updateCheckStatus('anomaly', anomalyErrors);

    // 入力修正提案の表示
    showSuggestions();

    // 総合ステータス更新
    updateOverallStatus();
  }

  function updateCheckStatus(checkType, errors) {
    const statusIcon = container.querySelector(`#${checkType}-status-icon`);
    const errorsDiv = container.querySelector(`#${checkType}-errors`);
    const checkDiv = container.querySelector(`#${checkType}-check`);

    if (errors.length === 0) {
      statusIcon.textContent = '✅';
      statusIcon.style.color = '#28a745';
      errorsDiv.textContent = 'チェック通過';
      checkDiv.style.borderLeftColor = '#28a745';
    } else {
      statusIcon.textContent = '❌';
      statusIcon.style.color = '#dc3545';
      errorsDiv.innerHTML = errors.map(err => `• ${err}`).join('<br>');
      checkDiv.style.borderLeftColor = '#dc3545';
      currentErrors.push(...errors);
    }
  }

  function showSuggestions() {
    const suggestionArea = container.querySelector('#suggestion-area');
    const suggestionsDiv = container.querySelector('#suggestions');
    const suggestions = [];

    const workContent = container.querySelector('#work-content').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;

    if (workContent && /^[0-9\s\-_]+$/.test(workContent)) {
      suggestions.push('作業内容には具体的な作業内容を文章で入力してください（例：配管工事、設備点検作業）');
    }

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      if (start >= end) {
        suggestions.push('開始時刻と終了時刻を確認し、正しい時間順序で入力してください');
      }
    }

    if (suggestions.length > 0) {
      suggestionsDiv.innerHTML = suggestions.map(s => `• ${s}`).join('<br>');
      suggestionArea.style.display = 'block';
    } else {
      suggestionArea.style.display = 'none';
    }
  }

  function updateOverallStatus() {
    const overallIcon = container.querySelector('#overall-status-icon');
    const saveStatus = container.querySelector('#save-status');
    const registerBtn = container.querySelector('#btn-register');

    if (currentErrors.length === 0) {
      overallIcon.textContent = '✅';
      overallIcon.style.color = '#28a745';
      saveStatus.textContent = '保存可能';
      saveStatus.style.color = '#28a745';
      registerBtn.disabled = false;
      registerBtn.style.opacity = '1';
    } else {
      overallIcon.textContent = '❌';
      overallIcon.style.color = '#dc3545';
      saveStatus.textContent = '保存不可 - エラーを修正してください';
      saveStatus.style.color = '#dc3545';
      registerBtn.disabled = true;
      registerBtn.style.opacity = '0.5';
    }
  }

  function isValidDate(dateString) {
    const date = new Date(dateString);
    return date instanceof Date && !isNaN(date);
  }

  function isValidTime(timeString) {
    return /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/.test(timeString);
  }

  function showGuidance(fieldName) {
    const guidancePanel = container.querySelector('#guidance-panel');
    const guidanceContent = container.querySelector('#guidance-content');

    const guidanceTexts = {
      'work-date': '作業を実施した日付を選択してください。未来の日付は選択できません。',
      'start-time': '作業開始時刻を24時間形式で入力してください（例：09:00）',
      'end-time': '作業終了時刻を24時間形式で入力してください（例：17:00）',
      'break-time': '休憩時間を分単位で入力してください（例：60）',
      'work-content': '具体的な作業内容を200文字以内で入力してください（例：配管工事、設備点検作業）',
      'work-location': '作業を実施した場所を入力してください（例：A棟1階）',
      'worker-name': '作業を担当した作業員の氏名を入力してください'
    };

    if (guidanceTexts[fieldName]) {
      guidanceContent.textContent = guidanceTexts[fieldName];
      guidancePanel.style.display = 'block';
    }
  }

  function hideGuidance() {
    const guidancePanel = container.querySelector('#guidance-panel');
    guidancePanel.style.display = 'none';
  }

  // イベントリスナー設定
  const inputs = ['work-date', 'start-time', 'end-time', 'break-time', 'work-content', 'work-location', 'worker-name'];
  inputs.forEach(inputId => {
    const input = container.querySelector(`#${inputId}`);
    input.addEventListener('input', performValidation);
    input.addEventListener('focus', () => showGuidance(inputId));
    input.addEventListener('blur', hideGuidance);
  });

  // 登録ボタン
  container.querySelector('#btn-register').addEventListener('click', async () => {
    if (currentErrors.length > 0) return;

    const workData = {
      作業日: container.querySelector('#work-date').value,
      作業開始時刻: `${container.querySelector('#work-date').value}T${container.querySelector('#start-time').value}`,
      作業終了時刻: `${container.querySelector('#work-date').value}T${container.querySelector('#end-time').value}`,
      作業内容: container.querySelector('#work-content').value,
      作業場所: container.querySelector('#work-location').value,
      作業員ID: 'current-user', // 実際の実装では現在のユーザーIDを使用
      プロジェクト名: 'デフォルトプロジェクト',
      作業種別: '一般作業',
      進捗状況: '完了',
      承認状態: '未承認',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user'
    };

    try {
      const saved = await window.aivicApi.save(1, workData);
      if (saved) {
        alert('工数記録が正常に登録されました');
        // フォームリセット
        inputs.forEach(inputId => {
          container.querySelector(`#${inputId}`).value = '';
        });
        performValidation();
      }
    } catch (error) {
      alert('登録に失敗しました');
    }
  });

  // エラー詳細確認ボタン
  container.querySelector('#btn-error-detail').addEventListener('click', () => {
    const modal = container.querySelector('#error-detail-modal');
    const content = container.querySelector('#error-detail-content');

    if (currentErrors.length === 0) {
      content.innerHTML = '<p style="color: var(--text); font-size: 13px;">現在エラーはありません。</p>';
    } else {
      content.innerHTML = currentErrors.map((error, index) => 
        `<div style="margin-bottom: 8px; padding: 8px; background: var(--bg-main); border-radius: 4px; border-left: 3px solid #dc3545;">
          <span style="font-size: 13px; color: var(--text);">${index + 1}. ${error}</span>
        </div>`
      ).join('');
    }

    modal.style.display = 'block';
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#error-detail-modal').style.display = 'none';
  });

  // エラーログ出力ボタン
  container.querySelector('#btn-export-log').addEventListener('click', () => {
    const logData = {
      timestamp: new Date().toISOString(),
      errors: currentErrors,
      inputData: {
        workDate: container.querySelector('#work-date').value,
        startTime: container.querySelector('#start-time').value,
        endTime: container.querySelector('#end-time').value,
        breakTime: container.querySelector('#break-time').value,
        workContent: container.querySelector('#work-content').value,
        workLocation: container.querySelector('#work-location').value,
        workerName: container.querySelector('#worker-name').value
      }
    };

    const blob = new Blob([JSON.stringify(logData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `error-log-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // 工数記録画面へ遷移
  container.querySelector('#btn-work-record').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 初期化
  loadExistingRecords().then(() => {
    performValidation();
  });
}

function(container, apiUrl, tables) {
  // エラー情報の管理
  let errorInfo = {
    title: 'システムエラーが発生しました',
    code: 'E001',
    message: '申し訳ございませんが、システムで予期しないエラーが発生しました。しばらく時間をおいてから再度お試しください。',
    type: 'ネットワークエラー',
    location: '工数記録保存処理',
    technical: 'HTTP 500 - Internal Server Error',
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    retryCount: 0
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorInfo = { ...errorInfo, ...errorData };
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('.error-title').textContent = errorInfo.title;
    container.querySelector('[data-testid="error-code"]').textContent = `エラーコード: ${errorInfo.code}`;
    container.querySelector('[data-testid="error-message"]').textContent = errorInfo.message;
    container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;
    container.querySelector('#error-type').textContent = errorInfo.type;
    container.querySelector('#error-location').textContent = errorInfo.location;
    container.querySelector('#error-technical').textContent = errorInfo.technical;
  }

  // 初期表示
  updateErrorDisplay();

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', async function() {
    const button = this;
    const originalText = button.innerHTML;

    // ボタンを無効化
    button.disabled = true;
    button.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 11-6.219-8.56"/></svg> 再試行中...';

    try {
      // 再試行回数をカウント
      errorInfo.retryCount++;

      // ネットワーク接続チェック（簡易）
      if (!navigator.onLine) {
        throw new Error('ネットワーク接続がありません');
      }

      // API接続テスト
      if (apiUrl) {
        const response = await fetch(`${apiUrl}/api/health`, { 
          method: 'GET',
          timeout: 5000 
        });
        if (!response.ok) {
          throw new Error(`サーバーエラー: ${response.status}`);
        }
      }

      // 成功時は元の画面に戻る
      if (window.history.length > 1) {
        window.history.back();
      } else {
        window.showScreen('scr-1778907133295'); // 工数記録画面
      }

    } catch (error) {
      // 再試行失敗
      errorInfo.message = `再試行に失敗しました（${errorInfo.retryCount}回目）。${error.message}`;
      errorInfo.timestamp = new Date().toLocaleString('ja-JP', {
        year: 'numeric',
        month: '2-digit', 
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }).replace(/\//g, '/');

      updateErrorDisplay();

      // 連続失敗時は管理者連絡を促す
      if (errorInfo.retryCount >= 3) {
        const solutionContent = container.querySelector('.solution-content');
        solutionContent.innerHTML = `
          <p style="color: #ff4757; font-weight: 500;">再試行が${errorInfo.retryCount}回失敗しました。管理者にお問い合わせください。</p>
          <ul>
            <li>「管理者に連絡」ボタンから問題を報告する</li>
            <li>しばらく時間をおいてから再度お試しください</li>
            <li>緊急の場合は直接電話でお問い合わせください</li>
          </ul>
        `;
      }
    } finally {
      // ボタンを有効化
      button.disabled = false;
      button.innerHTML = originalText;
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', function() {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', function() {
    window.showScreen('scr-1778907133295'); // 工数記録画面（ホーム）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', async function() {
    const button = this;
    const originalText = button.innerHTML;

    try {
      button.disabled = true;
      button.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 11-6.219-8.56"/></svg> 送信中...';

      // 管理者連絡機能をテスト
      if (apiUrl) {
        const response = await fetch(`${apiUrl}/api/support/contact`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            errorCode: errorInfo.code,
            errorMessage: errorInfo.message,
            errorDetails: {
              type: errorInfo.type,
              location: errorInfo.location,
              technical: errorInfo.technical,
              timestamp: errorInfo.timestamp,
              retryCount: errorInfo.retryCount
            },
            userAgent: navigator.userAgent,
            url: window.location.href
          })
        });

        if (!response.ok) {
          throw new Error('連絡機能が利用できません');
        }

        // 成功時
        alert('管理者に問題を報告しました。対応をお待ちください。');

      } else {
        throw new Error('連絡機能が設定されていません');
      }

    } catch (error) {
      // 連絡機能エラー時は連絡先情報を表示
      container.querySelector('#contact-info-card').classList.remove('hidden');
      container.querySelector('#contact-info-card').scrollIntoView({ behavior: 'smooth' });

    } finally {
      button.disabled = false;
      button.innerHTML = originalText;
    }
  });

  // エラー詳細表示ボタン
  container.querySelector('#btn-details').addEventListener('click', function() {
    const detailsCard = container.querySelector('#error-details-card');
    const button = this;

    if (detailsCard.classList.contains('hidden')) {
      // 詳細情報が取得できない場合のシミュレーション
      if (Math.random() < 0.1) { // 10%の確率で詳細取得失敗
        errorInfo.technical = 'エラーの詳細情報を取得できませんでした';
        container.querySelector('#error-technical').textContent = errorInfo.technical;
      }

      detailsCard.classList.remove('hidden');
      button.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="18 15 12 9 6 15"></polyline></svg> 詳細を隠す';
      detailsCard.scrollIntoView({ behavior: 'smooth' });
    } else {
      detailsCard.classList.add('hidden');
      button.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle><circle cx="5" cy="12" r="1"></circle></svg> エラー詳細表示';
    }
  });

  // ネットワーク状態の監視
  window.addEventListener('online', function() {
    const solutionContent = container.querySelector('.solution-content');
    solutionContent.innerHTML = `
      <p style="color: #2ed573; font-weight: 500;">ネットワーク接続が復旧しました。再試行をお試しください。</p>
      <ul>
        <li>「再試行」ボタンをクリックして操作をやり直す</li>
        <li>問題が解決しない場合は管理者にお問い合わせください</li>
      </ul>
    `;
  });

  window.addEventListener('offline', function() {
    errorInfo.type = 'ネットワーク切断';
    errorInfo.message = 'ネットワーク接続が切断されました。接続を確認してから再試行してください。';
    updateErrorDisplay();

    const solutionContent = container.querySelector('.solution-content');
    solutionContent.innerHTML = `
      <p style="color: #ff4757; font-weight: 500;">ネットワーク接続が切断されています。</p>
      <ul>
        <li>Wi-Fiまたはモバイルデータ接続を確認する</li>
        <li>接続復旧後に「再試行」ボタンをクリックする</li>
        <li>問題が続く場合は管理者にお問い合わせください</li>
      </ul>
    `;
  });

  // セッション切れの検出
  if (urlParams.get('session') === 'expired') {
    errorInfo.title = 'セッションが切れました';
    errorInfo.code = 'E401';
    errorInfo.message = 'ログインセッションの有効期限が切れました。再度ログインしてください。';
    errorInfo.type = '認証エラー';

    updateErrorDisplay();

    // ログイン画面へのボタンを追加
    const primaryActions = container.querySelector('.primary-actions');
    const loginButton = document.createElement('button');
    loginButton.className = 'action-btn';
    loginButton.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"></path><polyline points="10 17 15 12 10 7"></polyline><line x1="15" y1="12" x2="3" y2="12"></line></svg> ログイン画面へ';
    loginButton.addEventListener('click', function() {
      window.location.href = './login.html';
    });
    primaryActions.appendChild(loginButton);
  }

  // 長いエラーメッセージの制限
  const messageElement = container.querySelector('[data-testid="error-message"]');
  if (errorInfo.message.length > 500) {
    const truncatedMessage = errorInfo.message.substring(0, 500) + '...';
    messageElement.textContent = truncatedMessage;
    messageElement.title = errorInfo.message; // ホバーで全文表示
  }
}

function(container, apiUrl, tables) {
  let currentAnomalies = [];
  let isValidationRunning = false;
  let selectedAnomalies = new Set();

  // 異常値検出結果の再描画
  function renderAnomalies(anomalies) {
    const tbody = container.querySelector('#anomaly-tbody');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!anomalies || anomalies.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');
    tbody.innerHTML = anomalies.map(anomaly => `
      <tr data-id="${anomaly.id}" style="height: 36px;">
        <td style="padding: 6px 10px;">
          <input type="checkbox" class="anomaly-checkbox" data-id="${anomaly.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${new Date(anomaly.検出日時).toLocaleString('ja-JP')}
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${anomaly.ユーザーID || ''}
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${anomaly.異常値種別 || ''}
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${anomaly.検出項目 || ''}
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${anomaly.検出値 || ''}
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          ${anomaly.閾値 || ''}
        </td>
        <td style="padding: 6px 10px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
                       background: ${getSeverityColor(anomaly.重要度)}; color: #fff;">
            ${anomaly.重要度 || ''}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
                       background: ${getStatusColor(anomaly.確認状況)}; color: #fff;">
            ${anomaly.確認状況 || ''}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary correction-btn" data-id="${anomaly.id}" style="font-size: 12px; padding: 4px 8px;">
            修正
          </button>
        </td>
      </tr>
    `).join('');
  }

  function getSeverityColor(severity) {
    switch(severity) {
      case '高': return '#ef4444';
      case '中': return '#f59e0b';
      case '低': return '#10b981';
      default: return '#6b7280';
    }
  }

  function getStatusColor(status) {
    switch(status) {
      case '未確認': return '#ef4444';
      case '確認済み': return '#f59e0b';
      case '対応済み': return '#10b981';
      default: return '#6b7280';
    }
  }

  // 初期データ読み込み
  async function loadAnomalies() {
    try {
      const anomalies = await window.aivicApi.list(4); // 異常値検出ログテーブル
      currentAnomalies = anomalies || [];
      renderAnomalies(currentAnomalies);
    } catch (error) {
      console.error('異常値データの読み込みに失敗:', error);
      currentAnomalies = tables[4]?.records || [];
      renderAnomalies(currentAnomalies);
    }
  }

  // 期間選択の監視
  function updateExecuteButton() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const executeBtn = container.querySelector('#btn-execute');

    executeBtn.disabled = !startDate || !endDate || isValidationRunning;
  }

  // 検証実行
  async function executeValidation() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!startDate || !endDate) {
      alert('検証期間を選択してください');
      return;
    }

    if (isValidationRunning) {
      alert('検証処理が実行中です。しばらくお待ちください。');
      return;
    }

    // 期間チェック
    const start = new Date(startDate);
    const end = new Date(endDate);
    const diffTime = Math.abs(end - start);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays > 365) {
      if (!confirm('1年以上の長期間が選択されています。処理に時間がかかる可能性がありますが、続行しますか？')) {
        return;
      }
    }

    isValidationRunning = true;
    container.querySelector('#btn-execute').disabled = true;
    container.querySelector('#progress-container').classList.remove('hidden');
    container.querySelector('#validation-complete-notification').classList.add('hidden');

    // 進捗バーのアニメーション
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    let progress = 0;

    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 95) progress = 95;

      progressBar.style.width = progress + '%';
      progressText.textContent = Math.round(progress) + '%';
    }, 200);

    try {
      // 模擬的な検証処理（実際はAPIコール）
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 完了
      clearInterval(progressInterval);
      progressBar.style.width = '100%';
      progressText.textContent = '100%';

      setTimeout(() => {
        container.querySelector('#progress-container').classList.add('hidden');
        container.querySelector('#validation-complete-notification').classList.remove('hidden');

        // 検証結果を再読み込み
        loadAnomalies();

        const summary = container.querySelector('#validation-summary');
        summary.textContent = `検証期間: ${startDate} ～ ${endDate}`;

        isValidationRunning = false;
        updateExecuteButton();
      }, 500);

    } catch (error) {
      clearInterval(progressInterval);
      alert('検証処理中にエラーが発生しました');
      container.querySelector('#progress-container').classList.add('hidden');
      isValidationRunning = false;
      updateExecuteButton();
    }
  }

  // フィルタリング
  function applyFilters() {
    const errorTypeFilter = container.querySelector('#filter-error-type').value;
    const severityFilter = container.querySelector('#filter-severity').value;

    let filtered = currentAnomalies;

    if (errorTypeFilter) {
      filtered = filtered.filter(a => a.異常値種別 === errorTypeFilter);
    }

    if (severityFilter) {
      filtered = filtered.filter(a => a.重要度 === severityFilter);
    }

    renderAnomalies(filtered);
  }

  // データ修正モーダル
  function openCorrectionModal(anomalyId) {
    const anomaly = currentAnomalies.find(a => a.id === anomalyId);
    if (!anomaly) return;

    const modal = container.querySelector('#correction-modal');
    const form = container.querySelector('#correction-form');

    form.innerHTML = `
      <div style="margin-bottom: 12px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">異常値種別</label>
        <input type="text" id="modal-error-type" value="${anomaly.異常値種別 || ''}" 
               style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%;">
      </div>
      <div style="margin-bottom: 12px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">検出値</label>
        <input type="text" id="modal-detected-value" value="${anomaly.検出値 || ''}" 
               style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%;">
      </div>
      <div style="margin-bottom: 12px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">重要度</label>
        <select id="modal-severity" style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%;">
          <option value="高" ${anomaly.重要度 === '高' ? 'selected' : ''}>高</option>
          <option value="中" ${anomaly.重要度 === '中' ? 'selected' : ''}>中</option>
          <option value="低" ${anomaly.重要度 === '低' ? 'selected' : ''}>低</option>
        </select>
      </div>
      <div style="margin-bottom: 12px;">
        <label style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px; display: block;">対応メモ</label>
        <textarea id="modal-memo" rows="3" placeholder="対応内容や備考を入力してください" 
                  style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; width: 100%; resize: vertical;">${anomaly.対応メモ || ''}</textarea>
      </div>
    `;

    modal.classList.remove('hidden');
    modal.dataset.anomalyId = anomalyId;
  }

  // データ修正保存
  async function saveCorrectionData() {
    const modal = container.querySelector('#correction-modal');
    const anomalyId = modal.dataset.anomalyId;

    const errorType = container.querySelector('#modal-error-type').value.trim();
    const detectedValue = container.querySelector('#modal-detected-value').value.trim();
    const severity = container.querySelector('#modal-severity').value;
    const memo = container.querySelector('#modal-memo').value.trim();

    // バリデーション
    if (!errorType) {
      alert('異常値種別を入力してください');
      return;
    }

    if (detectedValue.length > 1000) {
      alert('検出値は1000文字以内で入力してください');
      return;
    }

    if (memo.length > 1000) {
      alert('対応メモは1000文字以内で入力してください');
      return;
    }

    try {
      const updateData = {
        異常値種別: errorType,
        検出値: detectedValue,
        重要度: severity,
        対応メモ: memo,
        確認状況: '対応済み',
        確認日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.update(4, anomalyId, updateData);
      modal.classList.add('hidden');
      loadAnomalies();

    } catch (error) {
      console.error('データ修正に失敗:', error);
      alert('データの修正に失敗しました');
    }
  }

  // 一括承認
  async function bulkApprove() {
    if (selectedAnomalies.size === 0) {
      alert('承認する項目を選択してください');
      return;
    }

    if (!confirm(`選択した${selectedAnomalies.size}件のデータを承認しますか？`)) {
      return;
    }

    try {
      const promises = Array.from(selectedAnomalies).map(id => 
        window.aivicApi.update(4, id, {
          確認状況: '対応済み',
          確認日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        })
      );

      await Promise.all(promises);
      selectedAnomalies.clear();
      container.querySelector('#checkbox-select-all').checked = false;
      container.querySelector('#checkbox-bulk-approve').checked = false;
      container.querySelector('#btn-bulk-approve').disabled = true;

      loadAnomalies();

    } catch (error) {
      console.error('一括承認に失敗:', error);
      alert('一括承認処理に失敗しました');
    }
  }

  // 検証ログ出力
  function exportValidationLog() {
    if (currentAnomalies.length === 0) {
      alert('検証結果がありません');
      return;
    }

    const headers = ['検出日時', '作業員ID', '異常値種別', '検出項目', '検出値', '閾値', '重要度', '確認状況', '対応メモ'];
    const csvData = [
      headers.join(','),
      ...currentAnomalies.map(anomaly => [
        new Date(anomaly.検出日時).toLocaleString('ja-JP'),
        anomaly.ユーザーID || '',
        anomaly.異常値種別 || '',
        anomaly.検出項目 || '',
        anomaly.検出値 || '',
        anomaly.閾値 || '',
        anomaly.重要度 || '',
        anomaly.確認状況 || '',
        (anomaly.対応メモ || '').replace(/,/g, '，')
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector('#input-start-date').addEventListener('change', updateExecuteButton);
  container.querySelector('#input-end-date').addEventListener('change', updateExecuteButton);
  container.querySelector('#btn-execute').addEventListener('click', executeValidation);
  container.querySelector('#btn-revalidate').addEventListener('click', executeValidation);

  container.querySelector('#filter-error-type').addEventListener('change', applyFilters);
  container.querySelector('#filter-severity').addEventListener('change', applyFilters);

  container.querySelector('#btn-export-log').addEventListener('click', exportValidationLog);
  container.querySelector('#btn-bulk-approve').addEventListener('click', bulkApprove);

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#correction-modal').classList.add('hidden');
  });
  container.querySelector('#btn-cancel-correction').addEventListener('click', () => {
    container.querySelector('#correction-modal').classList.add('hidden');
  });
  container.querySelector('#btn-save-correction').addEventListener('click', saveCorrectionData);

  // チェックボックス関連
  container.querySelector('#checkbox-select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.anomaly-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedAnomalies.add(cb.dataset.id);
      } else {
        selectedAnomalies.delete(cb.dataset.id);
      }
    });
    container.querySelector('#btn-bulk-approve').disabled = selectedAnomalies.size === 0;
  });

  container.querySelector('#checkbox-bulk-approve').addEventListener('change', (e) => {
    container.querySelector('#btn-bulk-approve').disabled = !e.target.checked || selectedAnomalies.size === 0;
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 修正ボタン
    const correctionBtn = e.target.closest('.correction-btn');
    if (correctionBtn) {
      openCorrectionModal(correctionBtn.dataset.id);
      return;
    }
  });

  container.addEventListener('change', (e) => {
    // 個別チェックボックス
    if (e.target.classList.contains('anomaly-checkbox')) {
      if (e.target.checked) {
        selectedAnomalies.add(e.target.dataset.id);
      } else {
        selectedAnomalies.delete(e.target.dataset.id);
      }

      const bulkApproveCheckbox = container.querySelector('#checkbox-bulk-approve');
      container.querySelector('#btn-bulk-approve').disabled = !bulkApproveCheckbox.checked || selectedAnomalies.size === 0;

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.anomaly-checkbox');
      const checkedCount = container.querySelectorAll('.anomaly-checkbox:checked').length;
      container.querySelector('#checkbox-select-all').checked = checkedCount === allCheckboxes.length && allCheckboxes.length > 0;
    }
  });

  // 初期データ読み込み
  loadAnomalies();
  updateExecuteButton();
}

function(container, apiUrl, tables) {
  let interruptions = [];

  // 現在のユーザー情報を設定（仮のデータ）
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタのテーブルインデックス
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">選択してください</option>';
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    }
  }

  // 実働時間を計算
  function calculateActualHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#actual-hours').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    // 24時間をまたぐ場合の処理
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60)) - breakTime;

    if (diffMinutes < 0) {
      container.querySelector('#actual-hours').value = '';
      return;
    }

    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;
    container.querySelector('#actual-hours').value = `${hours}:${minutes.toString().padStart(2, '0')}`;
  }

  // 文字数カウント
  function updateCharCount() {
    const textarea = container.querySelector('#work-details');
    const charCount = container.querySelector('#char-count');
    charCount.textContent = textarea.value.length;
  }

  // 中断記録を表示
  function renderInterruptions() {
    const tbody = container.querySelector('#interruption-tbody');
    tbody.innerHTML = interruptions.map((item, index) => {
      const duration = item.終了時刻 ? calculateInterruptionDuration(item.開始時刻, item.終了時刻) : '進行中';
      return `
        <tr>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid var(--border);">${item.理由}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid var(--border);">${item.開始時刻}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid var(--border);">${item.終了時刻 || '-'}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid var(--border);">${duration}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid var(--border);">
            <button class="delete-interruption" data-index="${index}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 2px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 中断時間を計算
  function calculateInterruptionDuration(start, end) {
    if (!start || !end) return '';
    const startTime = new Date(`2000-01-01T${start}`);
    let endTime = new Date(`2000-01-01T${end}`);

    if (endTime <= startTime) {
      endTime.setDate(endTime.getDate() + 1);
    }

    const diffMs = endTime - startTime;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;
    return `${hours}:${minutes.toString().padStart(2, '0')}`;
  }

  // バリデーション
  function validateForm() {
    const errors = [];
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const workLocation = container.querySelector('#work-location').value;
    const workDetails = container.querySelector('#work-details').value;

    // 必須項目チェック
    if (!workDate) errors.push('作業日付は必須です');
    if (!workItem) errors.push('作業項目は必須です');
    if (!startTime) errors.push('開始時刻は必須です');
    if (!endTime) errors.push('終了時刻は必須です');
    if (!workLocation) errors.push('作業場所は必須です');
    if (!workDetails) errors.push('作業内容詳細は必須です');

    // 未来日付チェック
    if (workDate) {
      const today = new Date();
      const selectedDate = new Date(workDate);
      today.setHours(0, 0, 0, 0);
      selectedDate.setHours(0, 0, 0, 0);
      if (selectedDate > today) {
        errors.push('未来の日付は選択できません');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);

      // 同じ時刻チェック
      if (startTime === endTime) {
        errors.push('開始時刻と終了時刻が同じです');
      }
    }

    // 休憩時間チェック
    if (startTime && endTime && breakTime > 0) {
      const start = new Date(`2000-01-01T${startTime}`);
      let end = new Date(`2000-01-01T${endTime}`);

      if (end <= start) {
        end.setDate(end.getDate() + 1);
      }

      const totalMinutes = Math.floor((end - start) / (1000 * 60));
      if (breakTime >= totalMinutes) {
        errors.push('休憩時間が実働時間を超過しています');
      }
    }

    // 文字数チェック
    if (workDetails.length > 1000) {
      errors.push('作業内容詳細は1000文字以内で入力してください');
    }

    return errors;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  function hideError() {
    container.querySelector('#error-message').style.display = 'none';
  }

  // イベントリスナー設定
  container.querySelector('#start-time').addEventListener('change', calculateActualHours);
  container.querySelector('#end-time').addEventListener('change', calculateActualHours);
  container.querySelector('#break-time').addEventListener('input', calculateActualHours);
  container.querySelector('#work-details').addEventListener('input', updateCharCount);

  // 作業状況変更時の中断セクション表示制御
  container.querySelector('#work-status').addEventListener('change', function() {
    const interruptionSection = container.querySelector('#interruption-section');
    if (this.value === '中断') {
      interruptionSection.style.display = 'block';
    } else {
      interruptionSection.style.display = 'none';
    }
  });

  // 中断記録追加
  container.querySelector('#add-interruption').addEventListener('click', function() {
    const reason = container.querySelector('#interruption-reason').value;
    const startTime = container.querySelector('#interruption-start').value;
    const endTime = container.querySelector('#interruption-end').value;

    if (!reason || !startTime) {
      showError('中断理由と開始時刻は必須です');
      return;
    }

    interruptions.push({
      理由: reason,
      開始時刻: startTime,
      終了時刻: endTime
    });

    renderInterruptions();

    // フォームクリア
    container.querySelector('#interruption-reason').value = '';
    container.querySelector('#interruption-start').value = '';
    container.querySelector('#interruption-end').value = '';
    hideError();
  });

  // 中断記録削除
  container.addEventListener('click', function(e) {
    if (e.target.classList.contains('delete-interruption')) {
      const index = parseInt(e.target.dataset.index);
      interruptions.splice(index, 1);
      renderInterruptions();
    }
  });

  // 登録ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    hideError();

    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('、'));
      return;
    }

    const workData = {
      作業員ID: currentUser.id,
      作業日: container.querySelector('#work-date').value,
      作業開始時刻: `${container.querySelector('#work-date').value}T${container.querySelector('#start-time').value}`,
      作業終了時刻: `${container.querySelector('#work-date').value}T${container.querySelector('#end-time').value}`,
      作業時間: parseInt(container.querySelector('#actual-hours').value.split(':')[0]) * 60 + parseInt(container.querySelector('#actual-hours').value.split(':')[1]),
      プロジェクト名: container.querySelector('#work-item option:checked').textContent.split(' - ')[1] || '',
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item option:checked').textContent.split(' - ')[0] || '',
      作業内容: container.querySelector('#work-details').value,
      進捗状況: container.querySelector('#work-status').value,
      備考: '',
      承認状態: '未承認',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: currentUser.id
    };

    const saved = await window.aivicApi.save(1, workData); // 作業記録テーブル

    if (saved) {
      // 中断記録も保存
      for (const interruption of interruptions) {
        const interruptionData = {
          作業記録ID: saved.作業記録ID,
          中断開始日時: `${container.querySelector('#work-date').value}T${interruption.開始時刻}`,
          中断終了日時: interruption.終了時刻 ? `${container.querySelector('#work-date').value}T${interruption.終了時刻}` : null,
          中断理由区分: interruption.理由,
          中断理由詳細: '',
          中断時間: interruption.終了時刻 ? parseInt(calculateInterruptionDuration(interruption.開始時刻, interruption.終了時刻).split(':')[0]) * 60 + parseInt(calculateInterruptionDuration(interruption.開始時刻, interruption.終了時刻).split(':')[1]) : null,
          影響度: '中程度',
          対応状況: '対応中',
          記録者ID: currentUser.id,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };

        await window.aivicApi.save(2, interruptionData); // 中断記録テーブル
      }

      alert('工数記録が正常に登録されました');

      // フォームクリア
      container.querySelector('#work-entry-form').reset();
      container.querySelector('#worker-name').value = currentUser.name;
      container.querySelector('#actual-hours').value = '';
      interruptions = [];
      renderInterruptions();
      container.querySelector('#interruption-section').style.display = 'none';
      updateCharCount();
    }
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', function() {
    if (confirm('入力内容をクリアしますか？')) {
      container.querySelector('#work-entry-form').reset();
      container.querySelector('#worker-name').value = currentUser.name;
      container.querySelector('#actual-hours').value = '';
      interruptions = [];
      renderInterruptions();
      container.querySelector('#interruption-section').style.display = 'none';
      hideError();
      updateCharCount();
    }
  });

  // セカンダリボタンのホバー効果
  const secondaryButtons = container.querySelectorAll('button[style*="background: transparent"]');
  secondaryButtons.forEach(btn => {
    btn.addEventListener('mouseenter', function() {
      this.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', function() {
      this.style.background = 'transparent';
    });
  });

  // プライマリボタンのホバー効果
  const primaryButtons = container.querySelectorAll('button[style*="background: var(--primary)"]');
  primaryButtons.forEach(btn => {
    btn.addEventListener('mouseenter', function() {
      this.style.background = 'var(--primary-hover)';
    });
    btn.addEventListener('mouseleave', function() {
      this.style.background = 'var(--primary)';
    });
  });

  // 初期化
  loadWorkItems();
  updateCharCount();

  // 今日の日付を初期値に設定
  const today = new Date();
  container.querySelector('#work-date').value = today.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let breakRecords = [];
  let workItems = [];
  let selectedRecord = null;
  let originalBreakRecord = null;

  // 初期データ読み込み
  async function loadData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      populateTargetRecords();
      populateWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録のドロップダウンを設定
  function populateTargetRecords() {
    const select = container.querySelector('#target-record');
    select.innerHTML = '<option value="">記録を選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID;
      option.textContent = `${record.作業日?.split('T')[0] || ''} - ${record.プロジェクト名 || ''} (${record.作業種別 || ''})`;
      select.appendChild(option);
    });
  }

  // 作業項目のドロップダウンを設定
  function populateWorkItems() {
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
        select.appendChild(option);
      });
  }

  // 修正前データを表示
  function showOriginalData(record) {
    const originalDataDiv = container.querySelector('#original-data');
    const contentDiv = container.querySelector('#original-data-content');

    const workItem = workItems.find(item => item.作業項目ID === record.作業項目ID);
    const breakRecord = breakRecords.find(br => br.作業記録ID === record.作業記録ID);

    contentDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px;">
        <div><strong>作業日:</strong> ${record.作業日?.split('T')[0] || '-'}</div>
        <div><strong>作業項目:</strong> ${workItem?.作業項目名 || '-'}</div>
        <div><strong>開始時刻:</strong> ${record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</div>
        <div><strong>終了時刻:</strong> ${record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</div>
        <div><strong>中断時刻:</strong> ${breakRecord?.中断開始日時 ? new Date(breakRecord.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</div>
        <div><strong>中断理由:</strong> ${breakRecord?.中断理由区分 || '-'}</div>
      </div>
    `;

    originalDataDiv.style.display = 'block';
  }

  // フォームに値を設定
  function populateForm(record) {
    const workItem = workItems.find(item => item.作業項目ID === record.作業項目ID);
    const breakRecord = breakRecords.find(br => br.作業記録ID === record.作業記録ID);
    originalBreakRecord = breakRecord;

    container.querySelector('#work-date').value = record.作業日?.split('T')[0] || '';
    container.querySelector('#work-item').value = record.作業項目ID || '';

    if (record.作業開始時刻) {
      const startTime = new Date(record.作業開始時刻);
      container.querySelector('#start-time').value = startTime.toTimeString().slice(0, 5);
    }

    if (record.作業終了時刻) {
      const endTime = new Date(record.作業終了時刻);
      container.querySelector('#end-time').value = endTime.toTimeString().slice(0, 5);
    }

    if (breakRecord?.中断開始日時) {
      const breakTime = new Date(breakRecord.中断開始日時);
      container.querySelector('#break-time').value = breakTime.toTimeString().slice(0, 5);
    }

    container.querySelector('#break-reason').value = breakRecord?.中断理由区分 || '';

    calculateTimes();
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;

    let breakDuration = 0;
    let actualWorkTime = 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);

        if (breakTime) {
          const breakStart = new Date(`2000-01-01T${breakTime}:00`);
          if (breakStart >= start && breakStart <= end) {
            // 簡易的に30分の中断として計算
            breakDuration = 30;
          }
        }

        actualWorkTime = totalMinutes - breakDuration;

        container.querySelector('#break-duration').textContent = breakDuration > 0 ? `${breakDuration}分` : '-';
        container.querySelector('#actual-work-time').textContent = actualWorkTime > 0 ? `${Math.floor(actualWorkTime / 60)}時間${actualWorkTime % 60}分` : '-';
      }
    }
  }

  // バリデーション
  function validateForm() {
    const errors = [];
    const warnings = [];

    const targetRecord = container.querySelector('#target-record').value;
    const workDate = container.querySelector('#work-date').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;
    const correctionReason = container.querySelector('#correction-reason').value.trim();

    // 必須チェック
    if (!targetRecord) {
      errors.push('修正対象の記録を選択してください');
    }

    if (!correctionReason) {
      errors.push('修正理由を入力してください');
    }

    // 日付チェック
    if (workDate) {
      const date = new Date(workDate);
      const today = new Date();
      const minDate = new Date('1900-01-01');
      const maxDate = new Date('2099-12-31');

      if (date < minDate || date > maxDate) {
        errors.push('作業日付は1900年1月1日から2099年12月31日の間で入力してください');
      }

      if (date > today) {
        warnings.push('未来の日付が入力されています');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (start >= end) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }

      const totalHours = (end - start) / (1000 * 60 * 60);
      if (totalHours > 20) {
        warnings.push('24時間近い作業時間が入力されています。確認してください。');
      }
    }

    // 中断時刻チェック
    if (breakTime && startTime && endTime) {
      const breakStart = new Date(`2000-01-01T${breakTime}:00`);
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (breakStart < start || breakStart > end) {
        errors.push('中断時刻が作業時間外です');
      }
    }

    return { errors, warnings };
  }

  // エラー・警告表示
  function showValidationMessages(errors, warnings) {
    const errorArea = container.querySelector('#error-area');
    const warningArea = container.querySelector('#warning-area');
    const errorMessages = container.querySelector('#error-messages');
    const warningMessages = container.querySelector('#warning-messages');

    if (errors.length > 0) {
      errorMessages.innerHTML = errors.map(err => `<div>• ${err}</div>`).join('');
      errorArea.style.display = 'block';
    } else {
      errorArea.style.display = 'none';
    }

    if (warnings.length > 0) {
      warningMessages.innerHTML = warnings.map(warn => `<div>• ${warn}</div>`).join('');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 文字数カウント
  container.querySelector('#correction-reason').addEventListener('input', function() {
    const charCount = container.querySelector('#char-count');
    charCount.textContent = this.value.length;
  });

  // 修正対象記録選択
  container.querySelector('#target-record').addEventListener('change', function() {
    const recordId = this.value;
    if (recordId) {
      selectedRecord = workRecords.find(record => record.作業記録ID === recordId);
      if (selectedRecord) {
        showOriginalData(selectedRecord);
        populateForm(selectedRecord);
        container.querySelector('#edit-form').style.display = 'block';
      }
    } else {
      selectedRecord = null;
      container.querySelector('#original-data').style.display = 'none';
      container.querySelector('#edit-form').style.display = 'none';
    }
  });

  // 時間変更時の自動計算
  ['#start-time', '#end-time', '#break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', calculateTimes);
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!selectedRecord) {
      showValidationMessages(['修正対象の記録を選択してください'], []);
      return;
    }

    const validation = validateForm();
    showValidationMessages(validation.errors, validation.warnings);

    if (validation.errors.length > 0) {
      return;
    }

    try {
      const workDate = container.querySelector('#work-date').value;
      const workItemId = container.querySelector('#work-item').value;
      const startTime = container.querySelector('#start-time').value;
      const endTime = container.querySelector('#end-time').value;
      const breakTime = container.querySelector('#break-time').value;
      const breakReason = container.querySelector('#break-reason').value;
      const correctionReason = container.querySelector('#correction-reason').value.trim();

      // 作業記録更新
      const updateData = {
        作業日: workDate ? new Date(workDate).toISOString() : selectedRecord.作業日,
        作業項目ID: workItemId || selectedRecord.作業項目ID,
        作業開始時刻: startTime ? new Date(`${workDate}T${startTime}:00`).toISOString() : selectedRecord.作業開始時刻,
        作業終了時刻: endTime ? new Date(`${workDate}T${endTime}:00`).toISOString() : selectedRecord.作業終了時刻,
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.update(1, selectedRecord.作業記録ID, updateData);

      // 中断記録の更新または作成
      if (breakTime && breakReason) {
        const breakData = {
          作業記録ID: selectedRecord.作業記録ID,
          中断開始日時: new Date(`${workDate}T${breakTime}:00`).toISOString(),
          中断理由区分: breakReason,
          中断理由詳細: correctionReason,
          記録者ID: selectedRecord.作業員ID,
          更新日時: new Date().toISOString()
        };

        if (originalBreakRecord) {
          await window.aivicApi.update(2, originalBreakRecord.中断記録ID, breakData);
        } else {
          breakData.中断記録ID = crypto.randomUUID();
          breakData.対応状況 = '未対応';
          breakData.作成日時 = new Date().toISOString();
          await window.aivicApi.save(2, breakData);
        }
      }

      alert('修正が完了しました');

      // データ再読み込み
      await loadData();

      // フォームリセット
      container.querySelector('#target-record').value = '';
      container.querySelector('#original-data').style.display = 'none';
      container.querySelector('#edit-form').style.display = 'none';
      container.querySelector('#correction-reason').value = '';
      container.querySelector('#char-count').textContent = '0';
      showValidationMessages([], []);

    } catch (error) {
      console.error('保存エラー:', error);
      showValidationMessages(['保存に失敗しました'], []);
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  let attachedFiles = [];
  const maxFiles = 5;
  const maxFileSize = 5 * 1024 * 1024; // 5MB

  // 現在のユーザー情報を取得して報告者名に設定
  const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{}');
