  }

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item');
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタのテーブルインデックス
      if (workItems) {
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = item.作業項目名;
          workItemSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 下書きデータの読み込み
  function loadDraft() {
    const draft = JSON.parse(localStorage.getItem('emergencyReportDraft') || '{}');
    if (Object.keys(draft).length > 0) {
      if (draft.urgency) {
        const urgencyRadio = container.querySelector(`input[name="urgency"][value="${draft.urgency}"]`);
        if (urgencyRadio) urgencyRadio.checked = true;
      }
      if (draft.reportType) container.querySelector('#report-type').value = draft.reportType;
      if (draft.occurrenceDateTime) container.querySelector('#occurrence-datetime').value = draft.occurrenceDateTime;
      if (draft.occurrenceLocation) container.querySelector('#occurrence-location').value = draft.occurrenceLocation;
      if (draft.workItem) container.querySelector('#work-item').value = draft.workItem;
      if (draft.emergencyContent) {
        const contentTextarea = container.querySelector('#emergency-content');
        contentTextarea.value = draft.emergencyContent;
        updateCharCount();
      }
      if (draft.contactPhone) container.querySelector('#contact-phone').value = draft.contactPhone;
    }
  }

  // 文字数カウント更新
  function updateCharCount() {
    const textarea = container.querySelector('#emergency-content');
    const charCount = container.querySelector('#char-count');
    const currentLength = textarea.value.length;
    charCount.textContent = `(${currentLength}/1000)`;

    if (currentLength > 1000) {
      charCount.style.color = '#ff453a';
      showError('emergency-content-error', '文字数上限を超えています（1000文字以内）');
    } else {
      charCount.style.color = 'var(--text-muted)';
      hideError('emergency-content-error');
    }
  }

  // エラーメッセージ表示
  function showError(elementId, message) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.textContent = message;
      errorElement.style.display = 'block';
    }
  }

  // エラーメッセージ非表示
  function hideError(elementId) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.style.display = 'none';
    }
  }

  // 全エラーメッセージクリア
  function clearAllErrors() {
    const errorElements = container.querySelectorAll('.error-message');
    errorElements.forEach(el => el.style.display = 'none');
  }

  // バリデーション
  function validateForm() {
    clearAllErrors();
    let isValid = true;

    // 緊急度チェック
    const urgency = container.querySelector('input[name="urgency"]:checked');
    if (!urgency) {
      showError('urgency-error', '緊急度を選択してください');
      isValid = false;
    }

    // 報告種別チェック
    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      showError('report-type-error', '報告種別を選択してください');
      isValid = false;
    }

    // 発生日時チェック
    const occurrenceDateTime = container.querySelector('#occurrence-datetime').value;
    if (!occurrenceDateTime) {
      showError('occurrence-datetime-error', '発生日時を入力してください');
      isValid = false;
    } else {
      const inputDate = new Date(occurrenceDateTime);
      const now = new Date();
      if (inputDate > now) {
        showError('occurrence-datetime-error', '発生日時に未来の日付は入力できません');
        isValid = false;
      }
    }

    // 発生場所チェック
    const occurrenceLocation = container.querySelector('#occurrence-location').value.trim();
    if (!occurrenceLocation) {
      showError('occurrence-location-error', '発生場所を入力してください');
      isValid = false;
    }

    // 緊急事態内容チェック
    const emergencyContent = container.querySelector('#emergency-content').value.trim();
    if (!emergencyContent) {
      showError('emergency-content-error', '緊急事態内容を入力してください');
      isValid = false;
    } else if (emergencyContent.length > 1000) {
      showError('emergency-content-error', '文字数上限を超えています（1000文字以内）');
      isValid = false;
    }

    // 連絡先電話番号チェック
    const contactPhone = container.querySelector('#contact-phone').value.trim();
    if (!contactPhone) {
      showError('contact-phone-error', '連絡先電話番号を入力してください');
      isValid = false;
    } else {
      const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
      if (!phonePattern.test(contactPhone.replace(/[^\d-]/g, ''))) {
        showError('contact-phone-error', '正しい電話番号の形式で入力してください');
        isValid = false;
      }
    }

    return isValid;
  }

  // ファイル添付処理
  function handleFileSelect(files) {
    const fileArray = Array.from(files);

    for (const file of fileArray) {
      // ファイル数制限チェック
      if (attachedFiles.length >= maxFiles) {
        showError('photo-error', `添付できる画像は最大${maxFiles}枚です`);
        break;
      }

      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('photo-error', 'サポートされていないファイル形式です。jpg、png形式のファイルをアップロードしてください。');
        continue;
      }

      // ファイルサイズチェック
      if (file.size > maxFileSize) {
        showError('photo-error', 'ファイルサイズ上限を超えています（5MB以内）');
        continue;
      }

      attachedFiles.push(file);
      hideError('photo-error');
    }

    updatePhotoPreview();
  }

  // 写真プレビュー更新
  function updatePhotoPreview() {
    const previewContainer = container.querySelector('#photo-preview');
    previewContainer.innerHTML = '';

    attachedFiles.forEach((file, index) => {
      const previewItem = document.createElement('div');
      previewItem.style.cssText = 'position: relative; border-radius: 6px; overflow: hidden; background: rgba(0,0,0,0.1);';

      const img = document.createElement('img');
      img.style.cssText = 'width: 100%; height: 80px; object-fit: cover;';

      const reader = new FileReader();
      reader.onload = (e) => {
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);

      const removeBtn = document.createElement('button');
      removeBtn.innerHTML = '×';
      removeBtn.style.cssText = 'position: absolute; top: 4px; right: 4px; width: 20px; height: 20px; border: none; border-radius: 50%; background: rgba(0,0,0,0.7); color: #fff; font-size: 12px; cursor: pointer; display: flex; align-items: center; justify-content: center;';
      removeBtn.onclick = () => {
        attachedFiles.splice(index, 1);
        updatePhotoPreview();
      };

      previewItem.appendChild(img);
      previewItem.appendChild(removeBtn);
      previewContainer.appendChild(previewItem);
    });
  }

  // フォームデータ収集
  function collectFormData() {
    const urgency = container.querySelector('input[name="urgency"]:checked');
    return {
      緊急度: urgency ? urgency.value : '',
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value.trim(),
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value.trim(),
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value.trim(),
      添付ファイル数: attachedFiles.length,
      報告日時: new Date().toISOString(),
      状態: '報告済み'
    };
  }

  // 下書き保存
  function saveDraft() {
    const formData = collectFormData();
    localStorage.setItem('emergencyReportDraft', JSON.stringify(formData));

    const successMessage = container.querySelector('#draft-success-message');
    successMessage.style.display = 'block';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 3000);
  }

  // 緊急報告送信
  async function submitReport() {
    if (!validateForm()) {
      return;
    }

    const formData = collectFormData();

    try {
      // 緊急報告データを保存（異常値検出ログテーブルを使用）
      const saved = await window.aivicApi.save(4, {
        検出対象テーブル: '緊急報告',
        検出対象レコードID: crypto.randomUUID(),
        ユーザーID: currentUser.ユーザーID || crypto.randomUUID(),
        異常値種別: formData.報告種別,
        検出項目: '緊急事態内容',
        検出値: formData.緊急事態内容,
        閾値: formData.緊急度,
        重要度: formData.緊急度,
        確認状況: '未確認',
        通知送信フラグ: true,
        対応メモ: `発生場所: ${formData.発生場所}, 連絡先: ${formData.連絡先電話番号}`,
        検出日時: formData.報告日時
      });

      if (saved) {
        // 下書きデータをクリア
        localStorage.removeItem('emergencyReportDraft');

        // 成功メッセージ表示
        const successMessage = container.querySelector('#success-message');
        successMessage.style.display = 'block';

        // フォームをリセット
        container.querySelector('#emergency-form').reset();
        attachedFiles = [];
        updatePhotoPreview();
        updateCharCount();

        setTimeout(() => {
          successMessage.style.display = 'none';
        }, 5000);
      }
    } catch (error) {
      console.error('緊急報告の送信に失敗しました:', error);
    }
  }

  // イベントリスナー設定
  container.querySelector('#emergency-content').addEventListener('input', updateCharCount);

  container.querySelector('#btn-photo-attach').addEventListener('click', () => {
    container.querySelector('#photo-input').click();
  });

  container.querySelector('#photo-input').addEventListener('change', (e) => {
    handleFileSelect(e.target.files);
  });

  // ドラッグ&ドロップ
  const dropZone = container.querySelector('#photo-drop-zone');
  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
  });

  dropZone.addEventListener('dragleave', () => {
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    handleFileSelect(e.dataTransfer.files);
  });

  container.querySelector('#btn-draft-save').addEventListener('click', saveDraft);
  container.querySelector('#btn-submit').addEventListener('click', submitReport);

  container.querySelector('#btn-back-to-work').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期化
  loadWorkItems();
  loadDraft();
  updateCharCount();

  // 現在日時を発生日時のデフォルトに設定
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector('#occurrence-datetime').value = localDateTime;
}

function(container, apiUrl, tables) {
  let currentRecord = null;
  let originalRecord = null;
  let workItems = [];

  // 作業項目マスタを取得
  async function loadWorkItems() {
    const items = await window.aivicApi.list(3); // 作業項目マスタ
    if (items) {
      workItems = items.filter(item => item.有効フラグ);
      const workItemSelect = container.querySelector("#work-item");
      workItemSelect.innerHTML = '<option value="">選択してください</option>';
      workItems.forEach(item => {
        workItemSelect.innerHTML += `<option value="${item.作業項目ID}">${item.作業項目名}</option>`;
      });
    }
  }

  // 作業記録一覧を取得してドロップダウンに設定
  async function loadWorkRecords() {
    const records = await window.aivicApi.list(1); // 作業記録
    if (records) {
      const targetSelect = container.querySelector("#target-record");
      targetSelect.innerHTML = '<option value="">選択してください</option>';
      records.forEach(record => {
        const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
        const projectName = record.プロジェクト名 || '';
        const workType = record.作業種別 || '';
        targetSelect.innerHTML += `<option value="${record.作業記録ID}">${workDate} - ${projectName} - ${workType}</option>`;
      });
    }
  }

  // 時間計算関数
  function calculateWorkTime() {
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;

    if (!startTime || !endTime) {
      container.querySelector("#total-work-time").value = "";
      container.querySelector("#net-work-time").value = "";
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間跨ぎの場合
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = Math.max(0, totalMinutes - breakTime);

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector("#total-work-time").value = `${totalHours}時間${totalMins}分`;
    container.querySelector("#net-work-time").value = `${netHours}時間${netMins}分`;

    // 異常値チェック
    checkAbnormalValues(totalMinutes, breakTime);
  }

  // 異常値チェック
  function checkAbnormalValues(totalMinutes, breakTime) {
    const warningArea = container.querySelector("#warning-area");
    let warnings = [];

    if (totalMinutes === 0) {
      warnings.push("作業時間が0分です。開始時刻と終了時刻を確認してください。");
    }
    if (totalMinutes > 12 * 60) { // 12時間超過
      warnings.push("作業時間が12時間を超えています。異常な値の可能性があります。");
    }
    if (breakTime > totalMinutes) {
      warnings.push("中断時間が作業時間を超過しています。");
    }

    if (warnings.length > 0) {
      warningArea.innerHTML = warnings.join('<br>');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // エラー表示
  function showError(message) {
    const errorArea = container.querySelector("#error-area");
    errorArea.innerHTML = message;
    errorArea.style.display = 'block';
  }

  function hideError() {
    container.querySelector("#error-area").style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    hideError();

    const targetRecord = container.querySelector("#target-record").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const correctionReason = container.querySelector("#correction-reason").value.trim();

    if (!targetRecord) {
      showError("修正対象の作業記録を選択してください。");
      return false;
    }

    if (!startTime || !endTime) {
      showError("作業開始時刻と終了時刻を入力してください。");
      return false;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    if (totalMinutes === 0) {
      showError("作業開始時刻と終了時刻が同じです。正しい時刻を入力してください。");
      return false;
    }

    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;
    if (breakTime > totalMinutes) {
      showError("中断時間が作業時間を超過しています。");
      return false;
    }

    if (!correctionReason) {
      showError("修正理由を入力してください。");
      return false;
    }

    if (correctionReason.length > 500) {
      showError("修正理由は500文字以内で入力してください。");
      return false;
    }

    const workDetail = container.querySelector("#work-detail").value;
    if (workDetail.length > 1000) {
      showError("作業内容詳細は1000文字以内で入力してください。");
      return false;
    }

    return true;
  }

  // 作業記録選択時の処理
  container.querySelector("#target-record").addEventListener("change", async function() {
    const recordId = this.value;
    if (!recordId) {
      currentRecord = null;
      originalRecord = null;
      // フォームクリア
      container.querySelector("#work-date").value = "";
      container.querySelector("#start-time").value = "";
      container.querySelector("#end-time").value = "";
      container.querySelector("#break-time").value = "";
      container.querySelector("#work-item").value = "";
      container.querySelector("#work-detail").value = "";
      container.querySelector("#correction-reason").value = "";
      calculateWorkTime();
      return;
    }

    const records = await window.aivicApi.list(1);
    if (records) {
      currentRecord = records.find(r => r.作業記録ID === recordId);
      originalRecord = { ...currentRecord }; // 元データ保存

      if (currentRecord) {
        // フォームに値設定
        const workDate = new Date(currentRecord.作業日).toLocaleDateString('ja-JP');
        container.querySelector("#work-date").value = workDate;

        const startTime = new Date(currentRecord.作業開始時刻);
        const endTime = currentRecord.作業終了時刻? new Date(currentRecord.作業終了時刻) : null;

        container.querySelector("#start-time").value = startTime.toTimeString().slice(0, 5);
        if (endTime) {
          container.querySelector("#end-time").value = endTime.toTimeString().slice(0, 5);
        }

        // 中断時間を計算（中断記録から）
        const breakRecords = await window.aivicApi.list(2); // 中断記録
        if (breakRecords) {
          const totalBreakTime = breakRecords
            .filter(br => br.作業記録ID === recordId && br.中断時間)
            .reduce((sum, br) => sum + br.中断時間, 0);
          container.querySelector("#break-time").value = totalBreakTime || 0;
        }

        container.querySelector("#work-item").value = currentRecord.作業項目ID || "";
        container.querySelector("#work-detail").value = currentRecord.作業内容 || "";

        calculateWorkTime();
      }
    }
  });

  // 時間入力時の計算
  container.querySelector("#start-time").addEventListener("input", calculateWorkTime);
  container.querySelector("#end-time").addEventListener("input", calculateWorkTime);
  container.querySelector("#break-time").addEventListener("input", calculateWorkTime);

  // 元データ参照ボタン
  container.querySelector("#btn-view-original").addEventListener("click", function() {
    if (!originalRecord) {
      showError("修正対象の作業記録を選択してください。");
      return;
    }

    const modal = container.querySelector("#original-data-modal");
    const content = container.querySelector("#original-data-content");

    const startTime = new Date(originalRecord.作業開始時刻).toLocaleString('ja-JP');
    const endTime = originalRecord.作業終了時刻 ? new Date(originalRecord.作業終了時刻).toLocaleString('ja-JP') : '未設定';

    content.innerHTML = `
      <div><strong>作業日:</strong> ${new Date(originalRecord.作業日).toLocaleDateString('ja-JP')}</div>
      <div><strong>開始時刻:</strong> ${startTime}</div>
      <div><strong>終了時刻:</strong> ${endTime}</div>
      <div><strong>プロジェクト名:</strong> ${originalRecord.プロジェクト名 || ''}</div>
      <div><strong>作業場所:</strong> ${originalRecord.作業場所 || ''}</div>
      <div><strong>作業種別:</strong> ${originalRecord.作業種別 || ''}</div>
      <div><strong>作業内容:</strong> ${originalRecord.作業内容 || ''}</div>
      <div><strong>進捗状況:</strong> ${originalRecord.進捗状況 || ''}</div>
      <div><strong>備考:</strong> ${originalRecord.備考 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", function() {
    container.querySelector("#original-data-modal").style.display = 'none';
  });

  // 修正完了ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!validateForm()) return;

    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const breakTime = parseInt(container.querySelector("#break-time").value) || 0;
    const workItem = container.querySelector("#work-item").value;
    const workDetail = container.querySelector("#work-detail").value;
    const correctionReason = container.querySelector("#correction-reason").value;

    // 作業開始・終了時刻を更新
    const workDate = new Date(currentRecord.作業日).toISOString().split('T')[0];
    const startDateTime = new Date(`${workDate}T${startTime}:00`).toISOString();
    const endDateTime = new Date(`${workDate}T${endTime}:00`).toISOString();

    // 24時間跨ぎの場合の調整
    if (endTime <= startTime) {
      const endDate = new Date(`${workDate}T${endTime}:00`);
      endDate.setDate(endDate.getDate() + 1);
      endDateTime = endDate.toISOString();
    }

    const totalMinutes = (new Date(endDateTime) - new Date(startDateTime)) / (1000 * 60);

    const updateData = {
      作業開始時刻: startDateTime,
      作業終了時刻: endDateTime,
      作業時間: Math.max(0, totalMinutes - breakTime),
      作業内容: workDetail,
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentRecord.作業記録ID, updateData);
    if (updated) {
      // 中断記録も更新（簡略化のため既存を削除して新規作成）
      if (breakTime > 0) {
        const breakRecords = await window.aivicApi.list(2);
        if (breakRecords) {
          const existingBreaks = breakRecords.filter(br => br.作業記録ID === currentRecord.作業記録ID);
          for (const br of existingBreaks) {
            await window.aivicApi.delete(2, br.中断記録ID);
          }
        }

        await window.aivicApi.save(2, {
          中断記録ID: crypto.randomUUID(),
          作業記録ID: currentRecord.作業記録ID,
          中断開始日時: startDateTime,
          中断終了日時: startDateTime,
          中断理由区分: '修正による調整',
          中断理由詳細: correctionReason,
          中断時間: breakTime,
          影響度: '軽微',
          対応状況: '解決済み',
          記録者ID: currentRecord.作業員ID,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        });
      }

      alert('工数修正が完了しました。');
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期化
  loadWorkItems();
  loadWorkRecords();
}

function(container, apiUrl, tables) {
  let currentData = [];

  // DOM要素の取得
  const startDateInput = container.querySelector('#start-date');
  const endDateInput = container.querySelector('#end-date');
  const workerSelect = container.querySelector('#worker-select');
  const workItemSelect = container.querySelector('#work-item-select');
  const locationSelect = container.querySelector('#location-select');
  const includeAnomalyCheckbox = container.querySelector('#include-anomaly');
  const includeInterruptionCheckbox = container.querySelector('#include-interruption');
  const conditionPreview = container.querySelector('#condition-preview');
  const dataCount = container.querySelector('#data-count');
  const errorMessage = container.querySelector('#error-message');
  const processingIndicator = container.querySelector('#processing-indicator');
  const previewTbody = container.querySelector('#preview-tbody');

  // 初期データの設定
  function initializeData() {
    // 作業員データの読み込み（ユーザーテーブル）
    if (tables[0]) {
      const users = tables[0].records || [];
      users.forEach(user => {
        const option = document.createElement('option');
        option.value = user.ユーザーID || user.id;
        option.textContent = user.氏名 || user.name || 'Unknown';
        workerSelect.appendChild(option);
      });
    }

    // 作業項目データの読み込み（作業項目マスタ）
    if (tables[3]) {
      const workItems = tables[3].records || [];
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID || item.id;
        option.textContent = item.作業項目名 || item.name || 'Unknown';
        workItemSelect.appendChild(option);
      });
    }

    // 作業場所データの読み込み（作業記録から重複除去）
    if (tables[1]) {
      const workRecords = tables[1].records || [];
      const locations = [...new Set(workRecords.map(r => r.作業場所).filter(Boolean))];
      locations.forEach(location => {
        const option = document.createElement('option');
        option.value = location;
        option.textContent = location;
        locationSelect.appendChild(option);
      });
    }
  }

  // プレビュー更新
  function updatePreview() {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const selectedWorkers = Array.from(workerSelect.selectedOptions).map(o => o.textContent);
    const selectedWorkItems = Array.from(workItemSelect.selectedOptions).map(o => o.textContent);
    const selectedLocation = locationSelect.value;
    const includeAnomaly = includeAnomalyCheckbox.checked;
    const includeInterruption = includeInterruptionCheckbox.checked;
    const outputFormat = container.querySelector('input[name="output-format"]:checked')?.value;

    let previewText = '';

    if (startDate && endDate) {
      previewText += `期間: ${startDate} ～ ${endDate}\n`;
    }

    if (selectedWorkers.length > 0) {
      previewText += `作業員: ${selectedWorkers.join(', ')}\n`;
    }

    if (selectedWorkItems.length > 0) {
      previewText += `作業項目: ${selectedWorkItems.join(', ')}\n`;
    }

    if (selectedLocation) {
      previewText += `作業場所: ${selectedLocation}\n`;
    }

    if (includeAnomaly) {
      previewText += `異常値データを含む\n`;
    }

    if (includeInterruption) {
      previewText += `中断記録を含む\n`;
    }

    if (outputFormat) {
      previewText += `出力形式: ${outputFormat.toUpperCase()}\n`;
    }

    conditionPreview.textContent = previewText || '条件を設定してください';
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // データ抽出とプレビュー表示
  async function extractData() {
    const startDate = startDateInput.value;
    const endDate = endDateInput.value;
    const selectedWorkerIds = Array.from(workerSelect.selectedOptions).map(o => o.value).filter(Boolean);
    const selectedWorkItemIds = Array.from(workItemSelect.selectedOptions).map(o => o.value).filter(Boolean);
    const selectedLocation = locationSelect.value;
    const includeAnomaly = includeAnomalyCheckbox.checked;
    const includeInterruption = includeInterruptionCheckbox.checked;
    const outputFormat = container.querySelector('input[name="output-format"]:checked')?.value;

    // バリデーション
    if (!startDate || !endDate) {
      showError('抽出期間を指定してください');
      return;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return;
    }

    processingIndicator.style.display = 'block';

    try {
      // 作業記録データの取得
      const workRecords = await window.aivicApi.list(1);
      if (!workRecords) {
        showError('データの取得に失敗しました');
        return;
      }

      // フィルタリング
      let filteredData = workRecords.filter(record => {
        const workDate = new Date(record.作業日 || record.date);
        const start = new Date(startDate);
        const end = new Date(endDate);

        if (workDate < start || workDate > end) return false;

        if (selectedWorkerIds.length > 0 && !selectedWorkerIds.includes(record.作業員ID)) return false;

        if (selectedLocation && record.作業場所 !== selectedLocation) return false;

        return true;
      });

      // 異常値除外処理
      if (!includeAnomaly) {
        const anomalyLogs = await window.aivicApi.list(4);
        if (anomalyLogs) {
          const anomalyRecordIds = anomalyLogs.map(log => log.検出対象レコードID);
          filteredData = filteredData.filter(record => !anomalyRecordIds.includes(record.作業記録ID || record.id));
        }
      }

      // 中断記録の処理
      if (includeInterruption) {
        const interruptionRecords = await window.aivicApi.list(2);
        if (interruptionRecords) {
          // 中断記録を含む場合の処理（実装は簡略化）
        }
      }

      currentData = filteredData;
      dataCount.textContent = `${filteredData.length}件`;

      // プレビューテーブルの更新
      if (filteredData.length === 0) {
        previewTbody.innerHTML = '<tr><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted);">該当するデータが見つかりませんでした</td></tr>';
      } else {
        const previewRows = filteredData.slice(0, 10).map(record => {
          const workerName = tables[0]?.records?.find(u => u.ユーザーID === record.作業員ID)?.氏名 || 'Unknown';
          return `
            <tr>
              <td style="padding: 6px 8px; color: var(--text);">${workerName}</td>
              <td style="padding: 6px 8px; color: var(--text);">${record.作業日 || ''}</td>
              <td style="padding: 6px 8px; color: var(--text);">${record.作業時間 || 0}分</td>
              <td style="padding: 6px 8px; color: var(--text);">${(record.作業内容 || '').substring(0, 20)}...</td>
            </tr>
          `;
        }).join('');

        previewTbody.innerHTML = previewRows;

        if (filteredData.length > 10) {
          previewTbody.innerHTML += `<tr><td colspan="4" style="padding: 6px 8px; text-align: center; color: var(--text-muted);">...他${filteredData.length - 10}件</td></tr>`;
        }
      }

      // 大量データの警告
      if (filteredData.length > 10000) {
        showError('抽出データが大量です。条件を絞り込むことをお勧めします。');
      }

    } catch (error) {
      showError('データ抽出中にエラーが発生しました');
      console.error('Extract error:', error);
    } finally {
      processingIndicator.style.display = 'none';
    }
  }

  // CSVダウンロード
  function downloadCSV() {
    if (currentData.length === 0) {
      showError('抽出データがありません');
      return;
    }

    const headers = ['作業員名', '作業日', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '進捗状況'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map(record => {
        const workerName = tables[0]?.records?.find(u => u.ユーザーID === record.作業員ID)?.氏名 || 'Unknown';
        return [
          `"${workerName}"`,
          `"${record.作業日 || ''}"`,
          `"${record.作業開始時刻 || ''}"`,
          `"${record.作業終了時刻 || ''}"`,
          `"${record.作業時間 || 0}"`,
          `"${record.プロジェクト名 || ''}"`,
          `"${record.作業場所 || ''}"`,
          `"${record.作業種別 || ''}"`,
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          `"${record.進捗状況 || ''}"`
        ].join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // Excelダウンロード（CSV形式で代用）
  function downloadExcel() {
    if (currentData.length === 0) {
      showError('抽出データがありません');
      return;
    }

    const headers = ['作業員名', '作業日', '作業開始時刻', '作業終了時刻', '作業時間', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '進捗状況'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map(record => {
        const workerName = tables[0]?.records?.find(u => u.ユーザーID === record.作業員ID)?.氏名 || 'Unknown';
        return [
          `"${workerName}"`,
          `"${record.作業日 || ''}"`,
          `"${record.作業開始時刻 || ''}"`,
          `"${record.作業終了時刻 || ''}"`,
          `"${record.作業時間 || 0}"`,
          `"${record.プロジェクト名 || ''}"`,
          `"${record.作業場所 || ''}"`,
          `"${record.作業種別 || ''}"`,
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          `"${record.進捗状況 || ''}"`
        ].join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.xlsx`;
    link.click();
  }

  // 条件クリア
  function clearConditions() {
    startDateInput.value = '';
    endDateInput.value = '';
    workerSelect.selectedIndex = -1;
    workItemSelect.selectedIndex = -1;
    locationSelect.selectedIndex = 0;
    includeAnomalyCheckbox.checked = false;
    includeInterruptionCheckbox.checked = false;
    container.querySelectorAll('input[name="output-format"]').forEach(radio => radio.checked = false);

    conditionPreview.textContent = '条件を設定してください';
    dataCount.textContent = '0件';
    previewTbody.innerHTML = '<tr><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted);">データを抽出してください</td></tr>';
    currentData = [];
  }

  // 条件保存
  function saveConditions() {
    const conditions = {
      startDate: startDateInput.value,
      endDate: endDateInput.value,
      workers: Array.from(workerSelect.selectedOptions).map(o => o.value),
      workItems: Array.from(workItemSelect.selectedOptions).map(o => o.value),
      location: locationSelect.value,
      includeAnomaly: includeAnomalyCheckbox.checked,
      includeInterruption: includeInterruptionCheckbox.checked,
      outputFormat: container.querySelector('input[name="output-format"]:checked')?.value
    };

    const conditionName = prompt('条件名を入力してください:');
    if (conditionName) {
      localStorage.setItem(`extract_condition_${conditionName}`, JSON.stringify(conditions));
      alert('条件が保存されました');
    }
  }

  // イベントリスナーの設定
  startDateInput.addEventListener('change', updatePreview);
  endDateInput.addEventListener('change', updatePreview);
  workerSelect.addEventListener('change', updatePreview);
  workItemSelect.addEventListener('change', updatePreview);
  locationSelect.addEventListener('change', updatePreview);
  includeAnomalyCheckbox.addEventListener('change', updatePreview);
  includeInterruptionCheckbox.addEventListener('change', updatePreview);
  container.querySelectorAll('input[name="output-format"]').forEach(radio => {
    radio.addEventListener('change', updatePreview);
  });

  container.querySelector('#btn-extract').addEventListener('click', async () => {
    await extractData();

    const outputFormat = container.querySelector('input[name="output-format"]:checked')?.value;
    if (outputFormat === 'csv') {
      downloadCSV();
    } else if (outputFormat === 'excel') {
      downloadExcel();
    }
  });

  container.querySelector('#btn-clear').addEventListener('click', clearConditions);
  container.querySelector('#btn-save-condition').addEventListener('click', saveConditions);
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // 初期化
  initializeData();
  updatePreview();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const emptyMessage = container.querySelector("#empty-message");
  const detailModal = container.querySelector("#detail-modal");
  const detailContent = container.querySelector("#detail-content");

  // ユーザーデータをマップ化
  const userMap = new Map();
  if (tables[0]) {
    (tables[0].records || []).forEach(user => {
      userMap.set(user.ユーザーID, user.氏名 || user.ユーザー名 || '不明');
    });
  }

  // 中断記録データをマップ化
  const breakMap = new Map();
  if (tables[2]) {
    (tables[2].records || []).forEach(breakRecord => {
      if (!breakMap.has(breakRecord.作業記録ID)) {
        breakMap.set(breakRecord.作業記録ID, []);
      }
      breakMap.get(breakRecord.作業記録ID).push(breakRecord);
    });
  }

  // 異常値検出関数
  function detectAnomalies(record) {
    const warnings = [];

    // 作業時間が24時間を超える場合
    if (record.作業時間 && record.作業時間 > 1440) { // 1440分 = 24時間
      warnings.push('24時間超過');
    }

    // 終了時刻が開始時刻より早い場合
    if (record.作業開始時刻 && record.作業終了時刻) {
      const start = new Date(record.作業開始時刻);
      const end = new Date(record.作業終了時刻);
      if (end < start) {
        warnings.push('時刻異常');
      }
    }

    // 中断時間が実働時間を超える場合
    const breaks = breakMap.get(record.作業記録ID) || [];
    const totalBreakTime = breaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
    if (record.作業時間 && totalBreakTime > record.作業時間) {
      warnings.push('中断時間異常');
    }

    return warnings;
  }

  // 時間フォーマット関数
  function formatTime(dateTimeStr) {
    if (!dateTimeStr) return '';
    const date = new Date(dateTimeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 作業時間フォーマット関数
  function formatWorkTime(minutes) {
    if (!minutes) return '';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}時間${mins}分`;
  }

  // 日付フォーマット関数
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.classList.remove('hidden');
      return;
    }

    emptyMessage.classList.add('hidden');
    tbody.innerHTML = rows.map(record => {
      const userName = userMap.get(record.作業員ID) || '不明';
      const breaks = breakMap.get(record.作業記録ID) || [];
      const totalBreakTime = breaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
      const warnings = detectAnomalies(record);

      const warningIcon = warnings.length > 0 
        ? `<span style="color: #ff6b6b; font-size: 16px;" title="${warnings.join(', ')}">⚠️</span>`
        : '';

      const statusBadge = record.承認状態 === '承認済み' 
        ? `<span style="background: #28a745; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">承認済み</span>`
        : record.承認状態 === '差し戻し'
        ? `<span style="background: #dc3545; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">差し戻し</span>`
        : `<span style="background: #ffc107; color: #000; padding: 2px 6px; border-radius: 4px; font-size: 11px;">未承認</span>`;

      const canEdit = record.承認状態 !== '承認済み';
      const editButton = canEdit 
        ? `<button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="margin-right: 4px;">修正</button>`
        : '';

      return `
        <tr data-id="${record.作業記録ID}" style="height: 36px; border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; color: var(--text);">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; color: var(--text);">${userName}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatWorkTime(record.作業時間)}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatWorkTime(totalBreakTime)}</td>
          <td style="padding: 6px 10px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.作業内容 || ''}</td>
          <td style="padding: 6px 10px;">${statusBadge}</td>
          <td style="padding: 6px 10px; text-align: center;">${warningIcon}</td>
          <td style="padding: 6px 10px; text-align: center;">
            ${editButton}
            <button class="action-btn secondary detail-btn" data-id="${record.作業記録ID}" style="margin-right: 4px;">詳細</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細表示関数
  function showDetail(recordId) {
    const record = (tables[1].records || []).find(r => r.作業記録ID === recordId);
    if (!record) return;

    const userName = userMap.get(record.作業員ID) || '不明';
    const breaks = breakMap.get(record.作業記録ID) || [];
    const totalBreakTime = breaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
    const warnings = detectAnomalies(record);

    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px;">
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業日</label>
          <div style="font-size: 13px; color: var(--text);">${formatDate(record.作業日)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業者</label>
          <div style="font-size: 13px; color: var(--text);">${userName}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">開始時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業開始時刻)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">終了時刻</label>
          <div style="font-size: 13px; color: var(--text);">${formatTime(record.作業終了時刻)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">実働時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatWorkTime(record.作業時間)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">中断時間</label>
          <div style="font-size: 13px; color: var(--text);">${formatWorkTime(totalBreakTime)}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">プロジェクト名</label>
          <div style="font-size: 13px; color: var(--text);">${record.プロジェクト名 || ''}</div>
        </div>
        <div>
          <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業場所</label>
          <div style="font-size: 13px; color: var(--text);">${record.作業場所 || ''}</div>
        </div>
      </div>
      <div style="margin-bottom: 16px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">作業内容</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.25); border-radius: 4px; white-space: pre-wrap;">${record.作業内容 || ''}</div>
      </div>
      ${record.備考 ? `
      <div style="margin-bottom: 16px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">備考</label>
        <div style="font-size: 13px; color: var(--text); padding: 8px; background: rgba(0,0,0,0.25); border-radius: 4px; white-space: pre-wrap;">${record.備考}</div>
      </div>
      ` : ''}
      ${warnings.length > 0 ? `
      <div style="margin-bottom: 16px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">警告</label>
        <div style="color: #ff6b6b; font-size: 13px;">${warnings.join(', ')}</div>
      </div>
      ` : ''}
    `;

    detailModal.classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    window.aivicApi.list(1).then(rows => {
      if (!rows || rows.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['作業日', '作業者', '開始時刻', '終了時刻', '実働時間', '中断時間', '作業内容', '作業場所', '承認状態'];
      const csvData = [headers.join(',')];

      rows.forEach(record => {
        const userName = userMap.get(record.作業員ID) || '不明';
        const breaks = breakMap.get(record.作業記録ID) || [];
        const totalBreakTime = breaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);

        const row = [
          formatDate(record.作業日),
          userName,
          formatTime(record.作業開始時刻),
          formatTime(record.作業終了時刻),
          formatWorkTime(record.作業時間),
          formatWorkTime(totalBreakTime),
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.作業場所 || '',
          record.承認状態 || ''
        ];
        csvData.push(row.join(','));
      });

      const csv = '\uFEFF' + csvData.join('\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `工数記録_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ表示
  renderRows(tables[1]?.records || []);

  // 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const dateValue = container.querySelector("#input-date").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    // 期間チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を指定してください');
      return;
    }

    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    let filteredRows = rows;

    // 単一日付フィルター
    if (dateValue) {
      filteredRows = filteredRows.filter(record => {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        return recordDate === dateValue;
      });
    }

    // 期間フィルター
    if (startDate || endDate) {
      filteredRows = filteredRows.filter(record => {
        const recordDate = new Date(record.作業日);
        if (startDate && recordDate < new Date(startDate)) return false;
        if (endDate && recordDate > new Date(endDate)) return false;
        return true;
      });
    }

    renderRows(filteredRows);
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 詳細モーダル閉じるボタン
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailModal.classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  detailModal.addEventListener("click", (e) => {
    if (e.target === detailModal) {
      detailModal.classList.add('hidden');
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この工数記録を削除しますか？")) return;

      const success = await window.aivicApi.delete(1, deleteBtn.dataset.id);
      if (success) {
        const rows = await window.aivicApi.list(1);
        renderRows(rows || []);
      }
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      window.showScreen("scr-1778907343735");
      return;
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }
  });
}

function(container, apiUrl, tables) {
  // 現在のユーザー情報を設定
  const currentUser = { id: 'user-001', name: '田中太郎' };
  container.querySelector('#worker-name').value = currentUser.name;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#work-date').value = today;

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector('#work-item');
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目名;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    }
  }
  loadWorkItems();

  // 文字数カウント
  const workDetails = container.querySelector('#work-details');
  const charCount = container.querySelector('#char-count');
  workDetails.addEventListener('input', () => {
    charCount.textContent = workDetails.value.length;
  });

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="padding: 8px 12px; background: rgba(220, 38, 38, 0.1); border: 1px solid rgba(220, 38, 38, 0.3); border-radius: 6px; color: #dc2626; font-size: 13px; margin-bottom: 8px;">${message}</div>`;
  }

  function clearErrors() {
    container.querySelector('#error-messages').innerHTML = '';
  }

  // バリデーション
  function validateForm() {
    clearErrors();
    const workDate = container.querySelector('#work-date').value;
    const projectName = container.querySelector('#project-name').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const workType = container.querySelector('#work-type').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workDetails = container.querySelector('#work-details').value;

    if (!workDate) {
      showError('作業日は必須です');
      return false;
    }

    // 未来日付チェック
    if (new Date(workDate) > new Date()) {
      showError('未来日付は選択できません');
      return false;
    }

    if (!projectName) {
      showError('プロジェクト名は必須です');
      return false;
    }

    if (!workItem) {
      showError('作業項目は必須です');
      return false;
    }

    if (!workLocation) {
      showError('作業場所は必須です');
      return false;
    }

    if (!workType) {
      showError('作業種別は必須です');
      return false;
    }

    if (!startTime) {
      showError('開始時刻は必須です');
      return false;
    }

    if (!workDetails) {
      showError('作業内容詳細は必須です');
      return false;
    }

    if (workDetails.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください');
      return false;
    }

    // 時刻チェック
    if (endTime && startTime >= endTime) {
      showError('開始時刻が終了時刻より後になっています');
      return false;
    }

    // 24時間チェック
    if (endTime) {
      const start = new Date(`${workDate}T${startTime}`);
      const end = new Date(`${workDate}T${endTime}`);
      if (end < start) {
        end.setDate(end.getDate() + 1); // 翌日扱い
      }
      const diffHours = (end - start) / (1000 * 60 * 60);
      if (diffHours >= 24) {
        showError('24時間以上の作業時間は入力できません');
        return false;
      }
    }

    // 中断時間チェック
    if (endTime) {
      const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
      const start = new Date(`${workDate}T${startTime}`);
      const end = new Date(`${workDate}T${endTime}`);
      if (end < start) {
        end.setDate(end.getDate() + 1);
      }
      const totalMinutes = (end - start) / (1000 * 60);
      if (breakTime > totalMinutes) {
        showError('中断時間は作業時間を超過できません');
        return false;
      }
    }

    return true;
  }

  // 工数計算
  function calculateWorkHours() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;
    const calculatedHours = container.querySelector('#calculated-hours');

    if (!startTime || !endTime) {
      calculatedHours.textContent = '0.0h';
      return 0;
    }

    const workDate = container.querySelector('#work-date').value || today;
    const start = new Date(`${workDate}T${startTime}`);
    const end = new Date(`${workDate}T${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1); // 翌日扱い
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const workMinutes = Math.max(0, totalMinutes - breakTime);
    const hours = (workMinutes / 60).toFixed(1);

    calculatedHours.textContent = `${hours}h`;
    return workMinutes;
  }

  // 工数計算ボタン
  container.querySelector('#btn-calculate').addEventListener('click', calculateWorkHours);

  // 時刻変更時の自動計算
  container.querySelector('#start-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#end-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#break-time').addEventListener('input', calculateWorkHours);

  // 中断記録追加
  container.querySelector('#btn-add-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439'); // 中断記録入力画面
  });

  // フォームデータ収集
  function collectFormData(isTemp = false) {
    const workDate = container.querySelector('#work-date').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const workMinutes = calculateWorkHours();

    return {
      作業員ID: currentUser.id,
      作業日: new Date(workDate).toISOString(),
      作業開始時刻: startTime ? new Date(`${workDate}T${startTime}`).toISOString() : null,
      作業終了時刻: endTime ? new Date(`${workDate}T${endTime}`).toISOString() : null,
      作業時間: endTime ? workMinutes : null,
      プロジェクト名: container.querySelector('#project-name').value,
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-type').value,
      作業内容: container.querySelector('#work-details').value,
      進捗状況: isTemp ? '一時保存' : (endTime ? '完了' : '作業中'),
      備考: '',
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: currentUser.id
    };
  }

  // 一時保存
  container.querySelector('#btn-temp-save').addEventListener('click', async () => {
    const formData = collectFormData(true);
    const saved = await window.aivicApi.save(1, formData); // 作業記録テーブル
    if (saved) {
      alert('一時保存しました');
    }
  });

  // 記録確定
  container.querySelector('#btn-save').addEventListener('click', async () => {
    if (!validateForm()) return;

    if (!confirm('記録を確定しますか？')) return;

    const formData = collectFormData(false);
    const saved = await window.aivicApi.save(1, formData); // 作業記録テーブル
    if (saved) {
      alert('工数記録を登録しました');
      // フォームクリア
      container.querySelector('#work-record-form').reset();
      container.querySelector('#worker-name').value = currentUser.name;
      container.querySelector('#work-date').value = today;
      container.querySelector('#break-time').value = '0';
      container.querySelector('#calculated-hours').textContent = '0.0h';
      container.querySelector('#char-count').textContent = '0';
      clearErrors();
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      container.querySelector('#work-record-form').reset();
      container.querySelector('#worker-name').value = currentUser.name;
      container.querySelector('#work-date').value = today;
      container.querySelector('#break-time').value = '0';
      container.querySelector('#calculated-hours').textContent = '0.0h';
      container.querySelector('#char-count').textContent = '0';
      clearErrors();
    }
  });

  // 作業履歴画面へ
  container.querySelector('#btn-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });
}
